//! CommonMark-aware block scanner used to locate headings in a document.
//!
//! The scanner tracks container blocks (block quotes and list items), leaf
//! blocks (paragraphs, fenced/indented code, HTML blocks) and reports ATX and
//! setext headings together with their byte offsets in the source.

use super::inline_text::{inline_plain_text, RefDefs};

#[derive(Debug, Clone)]
pub struct ScannedHeading {
    pub level: u8,
    /// Plain text of the heading (inline markup stripped).
    pub text: String,
    /// Byte offset of the first `#` (ATX) or the first text character (setext).
    pub offset: usize,
    pub setext: bool,
}

#[derive(Debug, Clone)]
enum Container {
    BlockQuote,
    ListItem { indent: usize },
}

#[derive(Debug, Clone)]
enum Leaf {
    None,
    Paragraph { start: usize, lines: Vec<String> },
    Fenced { ch: u8, len: usize },
    Indented,
    Html { kind: u8 },
}

struct Scanner<'a> {
    src: &'a str,
    containers: Vec<Container>,
    leaf: Leaf,
    headings: Vec<ScannedHeading>,
    refs: RefDefs,
    /// Raw paragraph texts waiting for inline processing (setext headings).
    pending_setext: Vec<(usize, u8, Vec<String>)>,
}

/// Width of a character for indentation purposes (tabs advance to the next multiple of 4).
fn advance_col(col: usize, ch: char) -> usize {
    if ch == '\t' {
        col + (4 - col % 4)
    } else {
        col + 1
    }
}

/// Count leading indentation (in columns) of `s`; returns (columns, byte length consumed).
fn leading_indent(s: &str) -> (usize, usize) {
    let mut col = 0;
    let mut bytes = 0;
    for ch in s.chars() {
        if ch == ' ' || ch == '\t' {
            col = advance_col(col, ch);
            bytes += ch.len_utf8();
        } else {
            break;
        }
    }
    (col, bytes)
}

fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

/// Try to parse an ATX heading from `s` (already stripped of container prefixes,
/// may have up to 3 spaces of indentation). Returns (level, byte index of '#', raw text).
pub fn atx_heading(s: &str) -> Option<(u8, usize, &str)> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = &s[bytes..];
    let hashes = rest.bytes().take_while(|&b| b == b'#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let after = &rest[hashes..];
    if !(after.is_empty() || after.starts_with(' ') || after.starts_with('\t')) {
        return None;
    }
    Some((hashes as u8, bytes, after))
}

/// Strip the optional closing sequence of `#` characters from ATX heading content.
pub fn strip_closing_hashes(raw: &str) -> &str {
    let t = raw.trim();
    if t.is_empty() {
        return t;
    }
    let trimmed_hashes = t.trim_end_matches('#');
    if trimmed_hashes.is_empty() {
        // the whole thing is hashes
        return "";
    }
    if trimmed_hashes.len() != t.len() {
        if trimmed_hashes.ends_with(' ') {
            return trimmed_hashes.trim_end_matches(' ');
        }
    }
    t
}

fn fence_open(s: &str) -> Option<(u8, usize)> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = &s[bytes..];
    let first = *rest.as_bytes().first()?;
    if first != b'`' && first != b'~' {
        return None;
    }
    let len = rest.bytes().take_while(|&b| b == first).count();
    if len < 3 {
        return None;
    }
    let info = &rest[len..];
    if first == b'`' && info.contains('`') {
        return None;
    }
    Some((first, len))
}

fn fence_close(s: &str, ch: u8, len: usize) -> bool {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return false;
    }
    let rest = &s[bytes..];
    let n = rest.bytes().take_while(|&b| b == ch).count();
    n >= len && rest[n..].trim().is_empty()
}

fn thematic_break(s: &str) -> bool {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return false;
    }
    let rest = s[bytes..].trim_end();
    let first = match rest.chars().next() {
        Some(c @ ('*' | '-' | '_')) => c,
        _ => return false,
    };
    let mut count = 0;
    for c in rest.chars() {
        if c == first {
            count += 1;
        } else if c != ' ' && c != '\t' {
            return false;
        }
    }
    count >= 3
}

/// Setext underline: returns heading level.
fn setext_underline(s: &str) -> Option<u8> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = s[bytes..].trim_end();
    if rest.is_empty() {
        return None;
    }
    if rest.bytes().all(|b| b == b'=') {
        Some(1)
    } else if rest.bytes().all(|b| b == b'-') {
        Some(2)
    } else {
        None
    }
}

/// Block quote marker: returns byte length consumed (indent + '>' + optional space).
fn blockquote_marker(s: &str) -> Option<usize> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = &s[bytes..];
    if !rest.starts_with('>') {
        return None;
    }
    let mut consumed = bytes + 1;
    if rest[1..].starts_with(' ') {
        consumed += 1;
    } else if rest[1..].starts_with('\t') {
        // a tab after '>' counts as one space of the marker; keep it simple
        consumed += 1;
    }
    Some(consumed)
}

/// List item marker. Returns (bytes consumed, content indent in columns, ordered, start number).
fn list_marker(s: &str, in_paragraph: bool) -> Option<(usize, usize, bool, Option<u64>)> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = &s[bytes..];
    let b = rest.as_bytes();
    let (marker_len, ordered, num) = if !b.is_empty() && (b[0] == b'-' || b[0] == b'*' || b[0] == b'+') {
        (1usize, false, None)
    } else {
        let digits = b.iter().take_while(|c| c.is_ascii_digit()).count();
        if digits == 0 || digits > 9 || digits >= b.len() {
            return None;
        }
        if b[digits] != b'.' && b[digits] != b')' {
            return None;
        }
        let n: u64 = rest[..digits].parse().ok()?;
        (digits + 1, true, Some(n))
    };
    let after = &rest[marker_len..];
    if after.is_empty() {
        if in_paragraph {
            return None;
        }
        return Some((bytes + marker_len, col + marker_len + 1, ordered, num));
    }
    if !(after.starts_with(' ') || after.starts_with('\t')) {
        return None;
    }
    // spaces after the marker
    let mut c = col + marker_len;
    let start_c = c;
    let mut consumed = 0;
    for ch in after.chars() {
        if ch == ' ' || ch == '\t' {
            c = advance_col(c, ch);
            consumed += ch.len_utf8();
        } else {
            break;
        }
    }
    let spaces = c - start_c;
    if after[consumed..].is_empty() {
        // marker followed only by whitespace: content indent is marker + 1
        if in_paragraph {
            return None;
        }
        return Some((bytes + marker_len + consumed, start_c + 1, ordered, num));
    }
    if in_paragraph && ordered && num != Some(1) {
        return None;
    }
    if spaces >= 5 {
        // treat as marker + 1 space, the rest is indented code
        return Some((bytes + marker_len + 1, start_c + 1, ordered, num));
    }
    Some((bytes + marker_len + consumed, c, ordered, num))
}

const HTML_BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

/// Detect the start of an HTML block. Returns the block kind (1..=7).
fn html_block_start(s: &str, in_paragraph: bool) -> Option<u8> {
    let (col, bytes) = leading_indent(s);
    if col > 3 {
        return None;
    }
    let rest = &s[bytes..];
    if !rest.starts_with('<') {
        return None;
    }
    let lower = rest.to_ascii_lowercase();
    // kind 1
    for tag in ["<script", "<pre", "<style", "<textarea"] {
        if lower.starts_with(tag) {
            let after = &lower[tag.len()..];
            if after.is_empty() || after.starts_with(' ') || after.starts_with('>') || after.starts_with('\t') {
                return Some(1);
            }
        }
    }
    if lower.starts_with("<!--") {
        return Some(2);
    }
    if lower.starts_with("<?") {
        return Some(3);
    }
    if rest.starts_with("<!") && rest[2..].starts_with(|c: char| c.is_ascii_alphabetic()) {
        return Some(4);
    }
    if lower.starts_with("<![cdata[") {
        return Some(5);
    }
    // kind 6
    let tag_start = if lower.starts_with("</") { 2 } else { 1 };
    let name: String = lower[tag_start..]
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric())
        .collect();
    if !name.is_empty() {
        let after = &lower[tag_start + name.len()..];
        let ok_after = after.is_empty()
            || after.starts_with(' ')
            || after.starts_with('\t')
            || after.starts_with('>')
            || after.starts_with("/>");
        if ok_after && HTML_BLOCK_TAGS.contains(&name.as_str()) {
            return Some(6);
        }
        // kind 7: complete open or closing tag alone on the line
        if !in_paragraph {
            let t = rest.trim_end();
            if t.ends_with('>') && !t.contains(' ') || complete_tag(t) {
                return Some(7);
            }
        }
    }
    None
}

fn complete_tag(t: &str) -> bool {
    // A loose check for a complete open/close tag occupying the whole line.
    let t = t.trim_end();
    if !t.ends_with('>') {
        return false;
    }
    let inner = &t[1..t.len() - 1];
    let inner = inner.strip_prefix('/').unwrap_or(inner);
    let mut chars = inner.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() => {}
        _ => return false,
    }
    !inner.contains('<') && !inner.contains('>')
}

fn html_block_end(s: &str, kind: u8) -> bool {
    let lower = s.to_ascii_lowercase();
    match kind {
        1 => lower.contains("</script>") || lower.contains("</pre>") || lower.contains("</style>") || lower.contains("</textarea>"),
        2 => lower.contains("-->"),
        3 => lower.contains("?>"),
        4 => lower.contains('>'),
        5 => lower.contains("]]>"),
        _ => false,
    }
}

impl<'a> Scanner<'a> {
    fn close_leaf(&mut self) {
        let leaf = std::mem::replace(&mut self.leaf, Leaf::None);
        if let Leaf::Paragraph { lines, .. } = leaf {
            // collect link reference definitions
            self.refs.collect_from_paragraph(&lines);
        }
    }

    fn close_containers_from(&mut self, idx: usize) {
        self.close_leaf();
        self.containers.truncate(idx);
    }

    fn process_line(&mut self, line_start: usize, line: &str) {
        let mut rest = line;
        let mut pos = 0usize; // byte offset within line
        let mut matched = 0usize;
        let mut all_matched = true;

        for (i, c) in self.containers.clone().iter().enumerate() {
            match c {
                Container::BlockQuote => {
                    if let Some(n) = blockquote_marker(rest) {
                        pos += n;
                        rest = &line[pos..];
                        matched = i + 1;
                    } else {
                        all_matched = false;
                        break;
                    }
                }
                Container::ListItem { indent } => {
                    if is_blank(rest) {
                        matched = i + 1;
                        continue;
                    }
                    let (col, _bytes) = leading_indent(rest);
                    if col >= *indent {
                        // consume `indent` columns
                        let mut c = 0;
                        let mut consumed = 0;
                        for ch in rest.chars() {
                            if c >= *indent {
                                break;
                            }
                            if ch == ' ' || ch == '\t' {
                                c = advance_col(c, ch);
                                consumed += ch.len_utf8();
                            } else {
                                break;
                            }
                        }
                        pos += consumed;
                        rest = &line[pos..];
                        matched = i + 1;
                    } else {
                        all_matched = false;
                        break;
                    }
                }
            }
        }

        if !all_matched {
            // Lazy continuation?
            let is_para = matches!(self.leaf, Leaf::Paragraph { .. });
            if is_para && !is_blank(rest) && !self.starts_block(rest, true) {
                if let Leaf::Paragraph { lines, .. } = &mut self.leaf {
                    lines.push(rest.trim().to_string());
                }
                return;
            }
            self.close_containers_from(matched);
        }

        // Leaf handling for code / html blocks
        match &self.leaf {
            Leaf::Fenced { ch, len } => {
                if all_matched || matched == self.containers.len() {
                    if fence_close(rest, *ch, *len) {
                        self.leaf = Leaf::None;
                    }
                    return;
                }
            }
            Leaf::Indented => {
                let (col, _) = leading_indent(rest);
                if col >= 4 || is_blank(rest) {
                    return;
                }
                self.leaf = Leaf::None;
            }
            Leaf::Html { kind } => {
                let kind = *kind;
                if kind == 6 || kind == 7 {
                    if is_blank(rest) {
                        self.leaf = Leaf::None;
                        return;
                    }
                    return;
                }
                if html_block_end(rest, kind) {
                    self.leaf = Leaf::None;
                }
                return;
            }
            _ => {}
        }

        // Open new containers / leaf blocks
        let mut opened_container = false;
        loop {
            let in_para = matches!(self.leaf, Leaf::Paragraph { .. }) && !opened_container;
            let (indent_col, _) = leading_indent(rest);

            if indent_col >= 4 {
                if in_para {
                    // continuation of paragraph
                    if let Leaf::Paragraph { lines, .. } = &mut self.leaf {
                        lines.push(rest.trim().to_string());
                    }
                    return;
                }
                if is_blank(rest) {
                    self.close_leaf();
                    return;
                }
                self.close_leaf();
                self.leaf = Leaf::Indented;
                return;
            }

            if is_blank(rest) {
                self.close_leaf();
                return;
            }

            if let Some(n) = blockquote_marker(rest) {
                self.close_leaf();
                self.containers.push(Container::BlockQuote);
                opened_container = true;
                pos += n;
                rest = &line[pos..];
                continue;
            }

            if let Some((level, hash_idx, raw)) = atx_heading(rest) {
                self.close_leaf();
                let offset = line_start + pos + hash_idx;
                let text_raw = strip_closing_hashes(raw).to_string();
                self.headings.push(ScannedHeading {
                    level,
                    text: text_raw, // processed later (needs ref defs)
                    offset,
                    setext: false,
                });
                return;
            }

            if let Some((ch, len)) = fence_open(rest) {
                self.close_leaf();
                self.leaf = Leaf::Fenced { ch, len };
                return;
            }

            if in_para {
                if let Some(level) = setext_underline(rest) {
                    if let Leaf::Paragraph { start, lines } = std::mem::replace(&mut self.leaf, Leaf::None) {
                        self.refs.collect_from_paragraph(&lines);
                        let (text_lines, para_start) = self.refs.strip_definitions(&lines, start, self.src);
                        if !text_lines.is_empty() {
                            self.pending_setext.push((para_start, level, text_lines));
                            self.headings.push(ScannedHeading {
                                level,
                                text: String::new(),
                                offset: para_start,
                                setext: true,
                            });
                        } else {
                            // paragraph consisted only of definitions; underline becomes a paragraph
                            self.leaf = Leaf::Paragraph { start: line_start + pos + leading_indent(rest).1, lines: vec![rest.trim().to_string()] };
                        }
                    }
                    return;
                }
            }

            if thematic_break(rest) {
                self.close_leaf();
                return;
            }

            if let Some((consumed, content_indent, _ordered, _num)) = list_marker(rest, in_para) {
                self.close_leaf();
                self.containers.push(Container::ListItem { indent: content_indent });
                opened_container = true;
                pos += consumed;
                rest = &line[pos..];
                if is_blank(rest) {
                    return;
                }
                continue;
            }

            if let Some(kind) = html_block_start(rest, in_para) {
                self.close_leaf();
                if (kind == 6 || kind == 7) && false {
                    return;
                }
                if html_block_end(rest, kind) && kind <= 5 {
                    // single-line html block
                    return;
                }
                self.leaf = Leaf::Html { kind };
                return;
            }

            // paragraph text
            let (_c, ws) = leading_indent(rest);
            match &mut self.leaf {
                Leaf::Paragraph { lines, .. } if !opened_container => {
                    lines.push(rest.trim().to_string());
                }
                _ => {
                    self.close_leaf();
                    self.leaf = Leaf::Paragraph {
                        start: line_start + pos + ws,
                        lines: vec![rest.trim().to_string()],
                    };
                }
            }
            return;
        }
    }

    /// Would `rest` start a new block that can interrupt a paragraph?
    fn starts_block(&self, rest: &str, lazy_check: bool) -> bool {
        let (col, _) = leading_indent(rest);
        if col >= 4 {
            return false;
        }
        if blockquote_marker(rest).is_some() {
            return true;
        }
        if atx_heading(rest).is_some() {
            return true;
        }
        if fence_open(rest).is_some() {
            return true;
        }
        if thematic_break(rest) {
            return true;
        }
        if list_marker(rest, true).is_some() {
            return true;
        }
        if html_block_start(rest, true).is_some() {
            return true;
        }
        let _ = lazy_check;
        false
    }
}

pub struct ScanResult {
    pub headings: Vec<ScannedHeading>,
    pub refs: RefDefs,
}

/// Scan a markdown document for headings.
pub fn scan_headings(src: &str) -> ScanResult {
    let mut sc = Scanner {
        src,
        containers: Vec::new(),
        leaf: Leaf::None,
        headings: Vec::new(),
        refs: RefDefs::default(),
        pending_setext: Vec::new(),
    };
    let mut offset = 0;
    for line in src.split_inclusive('\n') {
        let content = line.strip_suffix('\n').unwrap_or(line);
        let content = content.strip_suffix('\r').unwrap_or(content);
        sc.process_line(offset, content);
        offset += line.len();
    }
    sc.close_containers_from(0);

    // Resolve heading texts now that all reference definitions are known.
    let refs = sc.refs;
    let mut headings = sc.headings;
    let mut setext_iter = sc.pending_setext.into_iter();
    for h in headings.iter_mut() {
        if h.setext {
            if let Some((_, _, lines)) = setext_iter.next() {
                let joined = lines.join("\n");
                h.text = inline_plain_text(&joined, &refs);
            }
        } else {
            let raw = std::mem::take(&mut h.text);
            h.text = inline_plain_text(&raw, &refs);
        }
    }
    ScanResult { headings, refs }
}

/// The quirky 1-based line number used by the original tool: number of lines
/// in the source before `offset`, plus one.
pub fn line_number_at(src: &str, offset: usize) -> usize {
    src[..offset].lines().count() + 1
}

/// Offset of the start of the line following the line containing `offset`.
pub fn next_line_start(src: &str, offset: usize) -> usize {
    match src[offset..].find('\n') {
        Some(i) => offset + i + 1,
        None => src.len(),
    }
}
