//! CommonMark-style inline parser.
//!
//! Produces a tree of inline nodes. It is used to compute the plain text of
//! headings (concatenation of text runs, dropping code spans and raw HTML)
//! and for styled rendering in the TUI.

use std::collections::HashMap;

use crate::entities;

#[derive(Debug, Clone, PartialEq)]
pub enum Node {
    Text(String),
    Code(String),
    Html(String),
    SoftBreak,
    HardBreak,
    Emph(Vec<Node>),
    Strong(Vec<Node>),
    Strike(Vec<Node>),
    Link { url: String, title: String, children: Vec<Node> },
    Image { url: String, title: String, alt: Vec<Node> },
}

/// Link reference definitions collected from the document.
#[derive(Debug, Default, Clone)]
pub struct RefDefs {
    map: HashMap<String, (String, String)>,
}

pub fn normalize_label(label: &str) -> String {
    let mut out = String::new();
    let mut last_space = false;
    for ch in label.trim().chars() {
        if ch.is_whitespace() {
            if !last_space {
                out.push(' ');
            }
            last_space = true;
        } else {
            last_space = false;
            for c in ch.to_lowercase() {
                out.push(c);
            }
        }
    }
    out
}

impl RefDefs {
    pub fn get(&self, label: &str) -> Option<&(String, String)> {
        self.map.get(&normalize_label(label))
    }

    pub fn insert(&mut self, label: &str, url: String, title: String) {
        let key = normalize_label(label);
        if key.is_empty() {
            return;
        }
        self.map.entry(key).or_insert((url, title));
    }

    /// Scan the beginning of a paragraph for link reference definitions and
    /// record them.
    pub fn collect_from_paragraph(&mut self, lines: &[String]) {
        let joined = lines.join("\n");
        let mut rest: &str = &joined;
        loop {
            match parse_ref_def(rest) {
                Some((label, url, title, consumed)) => {
                    self.insert(&label, url, title);
                    rest = &rest[consumed..];
                    if rest.trim().is_empty() {
                        break;
                    }
                }
                None => break,
            }
        }
    }

    /// Remove leading reference definitions from paragraph lines; returns the
    /// remaining lines and the adjusted start offset of the remaining text.
    pub fn strip_definitions(&self, lines: &[String], start: usize, src: &str) -> (Vec<String>, usize) {
        let joined = lines.join("\n");
        let mut rest: &str = &joined;
        let mut consumed_total = 0;
        loop {
            match parse_ref_def(rest) {
                Some((_label, _url, _title, consumed)) => {
                    rest = &rest[consumed..];
                    consumed_total += consumed;
                }
                None => break,
            }
        }
        if consumed_total == 0 {
            return (lines.to_vec(), start);
        }
        // Count how many lines were consumed
        let consumed_lines = joined[..consumed_total].matches('\n').count();
        let remaining: Vec<String> = lines.iter().skip(consumed_lines).cloned().collect();
        // Find offset of the remaining text in the source
        let mut off = start;
        if let Some(first) = remaining.first() {
            if let Some(i) = src[start..].find(first.as_str()) {
                off = start + i;
            }
        }
        (remaining, off)
    }
}

/// Parse a link reference definition at the start of `s`.
/// Returns (label, destination, title, bytes consumed including trailing newline).
fn parse_ref_def(s: &str) -> Option<(String, String, String, usize)> {
    let b = s.as_bytes();
    let mut i = 0;
    // up to 3 spaces
    while i < b.len() && b[i] == b' ' && i < 3 {
        i += 1;
    }
    if i >= b.len() || b[i] != b'[' {
        return None;
    }
    i += 1;
    let label_start = i;
    let mut depth = 0;
    loop {
        if i >= b.len() {
            return None;
        }
        match b[i] {
            b'\\' => i += 2,
            b'[' => {
                depth += 1;
                i += 1;
            }
            b']' => {
                if depth == 0 {
                    break;
                }
                depth -= 1;
                i += 1;
            }
            _ => i += 1,
        }
    }
    if i > b.len() {
        return None;
    }
    let label = &s[label_start..i];
    if label.trim().is_empty() || label.len() > 999 {
        return None;
    }
    i += 1; // ]
    if i >= b.len() || b[i] != b':' {
        return None;
    }
    i += 1;
    // whitespace incl. up to one newline
    let mut newlines = 0;
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
        if b[i] == b'\n' {
            newlines += 1;
            if newlines > 1 {
                return None;
            }
        }
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    // destination
    let dest_start = i;
    let dest;
    if b[i] == b'<' {
        let mut j = i + 1;
        while j < b.len() && b[j] != b'>' && b[j] != b'\n' {
            j += 1;
        }
        if j >= b.len() || b[j] != b'>' {
            return None;
        }
        dest = s[i + 1..j].to_string();
        i = j + 1;
    } else {
        let mut j = i;
        let mut parens = 0i32;
        while j < b.len() {
            let c = b[j];
            if c == b' ' || c == b'\t' || c == b'\n' {
                break;
            }
            if c == b'\\' {
                j += 2;
                continue;
            }
            if c == b'(' {
                parens += 1;
            } else if c == b')' {
                parens -= 1;
                if parens < 0 {
                    break;
                }
            }
            j += 1;
        }
        if j > b.len() {
            j = b.len();
        }
        if j == dest_start {
            return None;
        }
        dest = s[dest_start..j].to_string();
        i = j;
    }
    // optional title
    let after_dest = i;
    let mut j = i;
    let mut saw_newline = false;
    while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
        if b[j] == b'\n' {
            if saw_newline {
                break;
            }
            saw_newline = true;
        }
        j += 1;
    }
    let mut title = String::new();
    let mut end = after_dest;
    let mut consumed_title = false;
    if j < b.len() && j > after_dest && (b[j] == b'"' || b[j] == b'\'' || b[j] == b'(') {
        let close = if b[j] == b'(' { b')' } else { b[j] };
        let mut k = j + 1;
        while k < b.len() && b[k] != close {
            if b[k] == b'\\' {
                k += 1;
            }
            k += 1;
        }
        if k < b.len() {
            let t = &s[j + 1..k];
            // rest of the line after the title must be blank
            let mut m = k + 1;
            while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
                m += 1;
            }
            if m >= b.len() || b[m] == b'\n' {
                title = unescape(t);
                end = if m < b.len() { m + 1 } else { m };
                consumed_title = true;
            }
        }
    }
    if !consumed_title {
        // rest of the destination line must be blank
        let mut m = after_dest;
        while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
            m += 1;
        }
        if m < b.len() && b[m] != b'\n' {
            return None;
        }
        end = if m < b.len() { m + 1 } else { m };
    }
    Some((label.to_string(), unescape(&dest), title, end))
}

pub fn is_ascii_punct(c: char) -> bool {
    c.is_ascii_punctuation()
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if is_ascii_punct(n) {
                    out.push(n);
                    chars.next();
                    continue;
                }
            }
            out.push(c);
        } else if c == '&' {
            // entity
            let rest: String = chars.clone().collect();
            if let Some((decoded, len)) = parse_entity(&rest) {
                out.push_str(&decoded);
                for _ in 0..len {
                    chars.next();
                }
            } else {
                out.push(c);
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Parse an entity reference whose `&` has already been consumed. `s` starts
/// right after the `&`. Returns (decoded text, chars consumed after '&').
pub fn parse_entity(s: &str) -> Option<(String, usize)> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    if b[0] == b'#' {
        let (hex, start) = if b.len() > 1 && (b[1] == b'x' || b[1] == b'X') { (true, 2) } else { (false, 1) };
        let mut i = start;
        while i < b.len() && (if hex { b[i].is_ascii_hexdigit() } else { b[i].is_ascii_digit() }) {
            i += 1;
        }
        let digits = &s[start..i];
        if digits.is_empty() || i >= b.len() || b[i] != b';' {
            return None;
        }
        if (hex && digits.len() > 6) || (!hex && digits.len() > 7) {
            return None;
        }
        let code = u32::from_str_radix(digits, if hex { 16 } else { 10 }).ok()?;
        let ch = if code == 0 { '\u{FFFD}' } else { char::from_u32(code).unwrap_or('\u{FFFD}') };
        return Some((ch.to_string(), i + 1));
    }
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i == 0 || i >= b.len() || b[i] != b';' {
        return None;
    }
    let name = &s[..i];
    entities::lookup(name).map(|v| (v.to_string(), i + 1))
}

// ---------------------------------------------------------------------------
// Tokenizer / parser
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Tok {
    Node(Node),
    Delim { ch: char, count: usize, can_open: bool, can_close: bool, active: bool },
    OpenBracket { image: bool, active: bool },
    CloseBracket,
}

fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation()
        || matches!(
            unicode_general_category(c),
            Some('P')
        )
}

fn unicode_general_category(c: char) -> Option<char> {
    // Minimal approximation: common Unicode punctuation blocks.
    let u = c as u32;
    if (0x2000..=0x206F).contains(&u) || (0x3000..=0x303F).contains(&u) || (0xFF00..=0xFF65).contains(&u) {
        return Some('P');
    }
    None
}

fn scan_autolink(s: &str) -> Option<(String, bool, usize)> {
    // s starts with '<'
    let b = s.as_bytes();
    let mut i = 1;
    while i < b.len() && b[i] != b'>' {
        let c = b[i];
        if c == b' ' || c == b'<' || c < 0x20 {
            return None;
        }
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let inner = &s[1..i];
    // scheme autolink
    if let Some(colon) = inner.find(':') {
        let scheme = &inner[..colon];
        if scheme.len() >= 2
            && scheme.len() <= 32
            && scheme.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false)
            && scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '.' || c == '-')
        {
            return Some((inner.to_string(), false, i + 1));
        }
    }
    // email autolink
    if let Some(at) = inner.find('@') {
        let local = &inner[..at];
        let domain = &inner[at + 1..];
        let local_ok = !local.is_empty()
            && local.chars().all(|c| c.is_ascii_alphanumeric() || ".!#$%&'*+/=?^_`{|}~-".contains(c));
        let domain_ok = !domain.is_empty()
            && domain.split('.').all(|part| {
                !part.is_empty()
                    && part.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
                    && !part.starts_with('-')
                    && !part.ends_with('-')
            });
        if local_ok && domain_ok {
            return Some((inner.to_string(), true, i + 1));
        }
    }
    None
}

fn scan_html_tag(s: &str) -> Option<usize> {
    // s starts with '<'. Returns length of the raw HTML construct.
    let b = s.as_bytes();
    if b.len() < 3 {
        return None;
    }
    if s.starts_with("<!--") {
        let rest = &s[4..];
        if rest.starts_with('>') || rest.starts_with("->") {
            return None;
        }
        return rest.find("-->").map(|i| 4 + i + 3);
    }
    if s.starts_with("<?") {
        return s[2..].find("?>").map(|i| 2 + i + 2);
    }
    if s.starts_with("<![CDATA[") {
        return s[9..].find("]]>").map(|i| 9 + i + 3);
    }
    if s.starts_with("<!") {
        if b[2].is_ascii_alphabetic() {
            return s[2..].find('>').map(|i| 2 + i + 1);
        }
        return None;
    }
    let mut i = 1;
    let closing = b[1] == b'/';
    if closing {
        i = 2;
    }
    // tag name
    if i >= b.len() || !b[i].is_ascii_alphabetic() {
        return None;
    }
    i += 1;
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'-') {
        i += 1;
    }
    if closing {
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i < b.len() && b[i] == b'>' {
            return Some(i + 1);
        }
        return None;
    }
    // attributes
    loop {
        let ws_start = i;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
        if b[i] == b'>' {
            return Some(i + 1);
        }
        if b[i] == b'/' {
            if i + 1 < b.len() && b[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if i == ws_start {
            return None;
        }
        // attribute name
        if !(b[i].is_ascii_alphabetic() || b[i] == b'_' || b[i] == b':') {
            return None;
        }
        i += 1;
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b"_.:-".contains(&b[i])) {
            i += 1;
        }
        // optional value
        let mut j = i;
        while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
            j += 1;
        }
        if j < b.len() && b[j] == b'=' {
            j += 1;
            while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
                j += 1;
            }
            if j >= b.len() {
                return None;
            }
            if b[j] == b'"' || b[j] == b'\'' {
                let q = b[j];
                j += 1;
                while j < b.len() && b[j] != q {
                    j += 1;
                }
                if j >= b.len() {
                    return None;
                }
                j += 1;
            } else {
                let start = j;
                while j < b.len() && !b" \t\n\"'=<>`".contains(&b[j]) {
                    j += 1;
                }
                if j == start {
                    return None;
                }
            }
            i = j;
        }
    }
}

fn scan_code_span(s: &str) -> Option<(String, usize)> {
    // s starts with '`'
    let b = s.as_bytes();
    let n = b.iter().take_while(|&&c| c == b'`').count();
    let mut i = n;
    while i < b.len() {
        if b[i] == b'`' {
            let m = b[i..].iter().take_while(|&&c| c == b'`').count();
            if m == n {
                let content = &s[n..i];
                let mut text: String = content.replace('\n', " ");
                if text.len() >= 2
                    && text.starts_with(' ')
                    && text.ends_with(' ')
                    && !text.chars().all(|c| c == ' ')
                {
                    text = text[1..text.len() - 1].to_string();
                }
                return Some((text, i + m));
            }
            i += m;
        } else {
            i += 1;
        }
    }
    None
}

struct InlineParser<'a> {
    refs: &'a RefDefs,
}

impl<'a> InlineParser<'a> {
    fn tokenize(&self, s: &str) -> Vec<Tok> {
        let mut toks: Vec<Tok> = Vec::new();
        let mut text = String::new();
        let chars: Vec<char> = s.chars().collect();
        let mut i = 0;

        macro_rules! flush {
            () => {
                if !text.is_empty() {
                    toks.push(Tok::Node(Node::Text(std::mem::take(&mut text))));
                }
            };
        }

        while i < chars.len() {
            let c = chars[i];
            match c {
                '\\' => {
                    if i + 1 < chars.len() && is_ascii_punct(chars[i + 1]) {
                        text.push(chars[i + 1]);
                        i += 2;
                    } else if i + 1 < chars.len() && chars[i + 1] == '\n' {
                        flush!();
                        toks.push(Tok::Node(Node::HardBreak));
                        i += 2;
                    } else {
                        text.push('\\');
                        i += 1;
                    }
                }
                '`' => {
                    let rest: String = chars[i..].iter().collect();
                    if let Some((code, len)) = scan_code_span(&rest) {
                        flush!();
                        toks.push(Tok::Node(Node::Code(code)));
                        i += rest[..len].chars().count();
                    } else {
                        let n = chars[i..].iter().take_while(|&&c| c == '`').count();
                        for _ in 0..n {
                            text.push('`');
                        }
                        i += n;
                    }
                }
                '&' => {
                    let rest: String = chars[i + 1..].iter().collect();
                    if let Some((decoded, len)) = parse_entity(&rest) {
                        text.push_str(&decoded);
                        i += 1 + len;
                    } else {
                        text.push('&');
                        i += 1;
                    }
                }
                '<' => {
                    let rest: String = chars[i..].iter().collect();
                    if let Some((url, email, len)) = scan_autolink(&rest) {
                        flush!();
                        let href = if email { format!("mailto:{}", url) } else { url.clone() };
                        toks.push(Tok::Node(Node::Link {
                            url: href,
                            title: String::new(),
                            children: vec![Node::Text(url)],
                        }));
                        i += rest[..len].chars().count();
                    } else if let Some(len) = scan_html_tag(&rest) {
                        flush!();
                        toks.push(Tok::Node(Node::Html(rest[..len].to_string())));
                        i += rest[..len].chars().count();
                    } else {
                        text.push('<');
                        i += 1;
                    }
                }
                '*' | '_' | '~' => {
                    let n = chars[i..].iter().take_while(|&&x| x == c).count();
                    let before = if i == 0 { ' ' } else { chars[i - 1] };
                    let after = if i + n >= chars.len() { ' ' } else { chars[i + n] };
                    let before_ws = before.is_whitespace();
                    let after_ws = after.is_whitespace();
                    let before_p = is_punct(before);
                    let after_p = is_punct(after);
                    let left_flanking = !after_ws && (!after_p || before_ws || before_p);
                    let right_flanking = !before_ws && (!before_p || after_ws || after_p);
                    let (can_open, can_close) = if c == '_' {
                        (
                            left_flanking && (!right_flanking || before_p),
                            right_flanking && (!left_flanking || after_p),
                        )
                    } else {
                        (left_flanking, right_flanking)
                    };
                    if c == '~' && n > 2 {
                        for _ in 0..n {
                            text.push('~');
                        }
                        i += n;
                        continue;
                    }
                    flush!();
                    toks.push(Tok::Delim { ch: c, count: n, can_open, can_close, active: true });
                    i += n;
                }
                '!' if i + 1 < chars.len() && chars[i + 1] == '[' => {
                    flush!();
                    toks.push(Tok::OpenBracket { image: true, active: true });
                    i += 2;
                }
                '[' => {
                    flush!();
                    toks.push(Tok::OpenBracket { image: false, active: true });
                    i += 1;
                }
                ']' => {
                    flush!();
                    toks.push(Tok::CloseBracket);
                    i += 1;
                }
                '\n' => {
                    // hard break if preceded by 2+ spaces
                    let trailing = text.len() - text.trim_end_matches(' ').len();
                    if trailing >= 2 {
                        text.truncate(text.len() - trailing);
                        flush!();
                        toks.push(Tok::Node(Node::HardBreak));
                    } else {
                        text.truncate(text.len() - trailing);
                        flush!();
                        toks.push(Tok::Node(Node::SoftBreak));
                    }
                    i += 1;
                    // strip leading spaces of next line
                    while i < chars.len() && chars[i] == ' ' {
                        i += 1;
                    }
                }
                _ => {
                    text.push(c);
                    i += 1;
                }
            }
        }
        flush!();
        toks
    }

    /// Try to parse the link tail starting at `pos` in `src` (right after `]`).
    /// Returns (url, title, chars consumed) for inline links, or for reference links.
    fn parse_link_tail(&self, src: &[char], pos: usize, label_text: &str) -> Option<(String, String, usize)> {
        if pos < src.len() && src[pos] == '(' {
            if let Some(r) = parse_inline_link_dest(src, pos) {
                return Some(r);
            }
        }
        if pos < src.len() && src[pos] == '[' {
            // full or collapsed reference
            let mut j = pos + 1;
            let mut label = String::new();
            let mut ok = false;
            while j < src.len() {
                if src[j] == '\\' && j + 1 < src.len() {
                    label.push(src[j]);
                    label.push(src[j + 1]);
                    j += 2;
                    continue;
                }
                if src[j] == '[' {
                    break;
                }
                if src[j] == ']' {
                    ok = true;
                    break;
                }
                label.push(src[j]);
                j += 1;
            }
            if ok {
                let key = if label.trim().is_empty() { label_text } else { &label };
                if let Some((url, title)) = self.refs.get(key) {
                    return Some((url.clone(), title.clone(), j + 1 - pos));
                }
                if label.trim().is_empty() {
                    return None;
                }
                // full reference with unknown label: fall through to shortcut
                if let Some((url, title)) = self.refs.get(label_text) {
                    return Some((url.clone(), title.clone(), 0));
                }
                return None;
            }
        }
        // shortcut reference
        if let Some((url, title)) = self.refs.get(label_text) {
            return Some((url.clone(), title.clone(), 0));
        }
        None
    }

    fn parse(&self, s: &str) -> Vec<Node> {
        let chars: Vec<char> = s.chars().collect();
        let toks = self.tokenize(s);
        // We need to map tokens back to source positions for link tails. To keep
        // things simple we re-scan: compute for each token its char offset.
        let positions = token_positions(&chars, &toks);
        let mut toks = toks;
        self.process_brackets(&mut toks, &chars, &positions);
        let mut nodes = self.finish(toks);
        merge_text(&mut nodes);
        nodes
    }

    fn process_brackets(&self, toks: &mut Vec<Tok>, chars: &[char], positions: &[(usize, usize)]) {
        // positions: (start, end) char offsets of each token in the original text
        let mut i = 0;
        let mut positions = positions.to_vec();
        while i < toks.len() {
            if let Tok::CloseBracket = toks[i] {
                // find nearest opener
                let mut opener = None;
                for j in (0..i).rev() {
                    if let Tok::OpenBracket { .. } = toks[j] {
                        opener = Some(j);
                        break;
                    }
                }
                let Some(j) = opener else {
                    toks[i] = Tok::Node(Node::Text("]".to_string()));
                    i += 1;
                    continue;
                };
                let (image, active) = match toks[j] {
                    Tok::OpenBracket { image, active } => (image, active),
                    _ => unreachable!(),
                };
                if !active {
                    toks[j] = Tok::Node(Node::Text(if image { "![".into() } else { "[".into() }));
                    toks[i] = Tok::Node(Node::Text("]".to_string()));
                    i += 1;
                    continue;
                }
                let label_start = positions[j].1;
                let label_end = positions[i].0;
                let label_text: String = chars[label_start..label_end].iter().collect();
                let after = positions[i].1;
                match self.parse_link_tail(chars, after, &label_text) {
                    Some((url, title, consumed)) => {
                        // inner tokens j+1..i
                        let inner: Vec<Tok> = toks.drain(j + 1..i).collect();
                        let inner_nodes = self.finish(inner);
                        let node = if image {
                            Node::Image { url, title, alt: inner_nodes }
                        } else {
                            Node::Link { url, title, children: inner_nodes }
                        };
                        // remove close bracket (now at index j+1) and opener
                        toks.remove(j + 1);
                        positions.drain(j + 1..=i);
                        toks[j] = Tok::Node(node);
                        positions[j] = (positions[j].0, after + consumed);
                        // Drop consumed chars tokens: tokens following that lie inside consumed range
                        let consumed_end = after + consumed;
                        let mut k = j + 1;
                        while k < toks.len() && positions[k].0 < consumed_end {
                            // token partially inside the consumed tail: trim text
                            if positions[k].1 <= consumed_end {
                                toks.remove(k);
                                positions.remove(k);
                            } else {
                                if let Tok::Node(Node::Text(t)) = &mut toks[k] {
                                    let cut = consumed_end - positions[k].0;
                                    let s: String = t.chars().skip(cut).collect();
                                    *t = s;
                                    positions[k].0 = consumed_end;
                                } else {
                                    toks.remove(k);
                                    positions.remove(k);
                                    continue;
                                }
                                break;
                            }
                        }
                        if !image {
                            // deactivate earlier link openers
                            for t in toks[..j].iter_mut() {
                                if let Tok::OpenBracket { image: false, active } = t {
                                    *active = false;
                                }
                            }
                        }
                        i = j + 1;
                    }
                    None => {
                        toks[j] = Tok::Node(Node::Text(if image { "![".into() } else { "[".into() }));
                        toks[i] = Tok::Node(Node::Text("]".to_string()));
                        i += 1;
                    }
                }
            } else {
                i += 1;
            }
        }
        // leftover openers
        for t in toks.iter_mut() {
            if let Tok::OpenBracket { image, .. } = t {
                let s = if *image { "![" } else { "[" };
                *t = Tok::Node(Node::Text(s.to_string()));
            }
        }
    }

    /// Run emphasis processing on a token list and convert to nodes.
    fn finish(&self, toks: Vec<Tok>) -> Vec<Node> {
        let mut toks = toks;
        process_emphasis(&mut toks);
        toks.into_iter()
            .map(|t| match t {
                Tok::Node(n) => n,
                Tok::Delim { ch, count, .. } => Node::Text(std::iter::repeat(ch).take(count).collect()),
                Tok::OpenBracket { image, .. } => Node::Text(if image { "![".into() } else { "[".into() }),
                Tok::CloseBracket => Node::Text("]".into()),
            })
            .collect()
    }
}

fn parse_inline_link_dest(src: &[char], pos: usize) -> Option<(String, String, usize)> {
    // src[pos] == '('
    let mut i = pos + 1;
    while i < src.len() && src[i].is_whitespace() {
        i += 1;
    }
    let mut url = String::new();
    if i < src.len() && src[i] == '<' {
        i += 1;
        while i < src.len() && src[i] != '>' {
            if src[i] == '\n' || src[i] == '<' {
                return None;
            }
            if src[i] == '\\' && i + 1 < src.len() && is_ascii_punct(src[i + 1]) {
                url.push(src[i + 1]);
                i += 2;
                continue;
            }
            url.push(src[i]);
            i += 1;
        }
        if i >= src.len() {
            return None;
        }
        i += 1;
    } else {
        let mut depth = 0;
        while i < src.len() {
            let c = src[i];
            if c.is_whitespace() || (c as u32) < 0x20 {
                break;
            }
            if c == '\\' && i + 1 < src.len() && is_ascii_punct(src[i + 1]) {
                url.push(src[i + 1]);
                i += 2;
                continue;
            }
            if c == '(' {
                depth += 1;
            } else if c == ')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            url.push(c);
            i += 1;
        }
        if depth != 0 {
            return None;
        }
    }
    let mut title = String::new();
    let ws_start = i;
    while i < src.len() && src[i].is_whitespace() {
        i += 1;
    }
    if i < src.len() && i > ws_start && (src[i] == '"' || src[i] == '\'' || src[i] == '(') {
        let close = if src[i] == '(' { ')' } else { src[i] };
        i += 1;
        while i < src.len() && src[i] != close {
            if src[i] == '\\' && i + 1 < src.len() && is_ascii_punct(src[i + 1]) {
                title.push(src[i + 1]);
                i += 2;
                continue;
            }
            title.push(src[i]);
            i += 1;
        }
        if i >= src.len() {
            return None;
        }
        i += 1;
        while i < src.len() && src[i].is_whitespace() {
            i += 1;
        }
    }
    if i < src.len() && src[i] == ')' {
        let url = unescape_entities_only(&url);
        return Some((url, title, i + 1 - pos));
    }
    None
}

fn unescape_entities_only(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '&' {
            let rest: String = chars.clone().collect();
            if let Some((decoded, len)) = parse_entity(&rest) {
                out.push_str(&decoded);
                for _ in 0..len {
                    chars.next();
                }
                continue;
            }
        }
        out.push(c);
    }
    out
}

/// Compute (start, end) char positions for each token by re-walking the source.
fn token_positions(chars: &[char], toks: &[Tok]) -> Vec<(usize, usize)> {
    // Re-tokenize positions by simulating the tokenizer's consumption. To stay
    // robust we approximate: we walk the chars and match each token's textual
    // footprint in order.
    let mut positions = Vec::with_capacity(toks.len());
    let mut i = 0;
    for t in toks {
        let start = i;
        let len = token_source_len(chars, i, t);
        i += len;
        positions.push((start, i));
    }
    positions
}

fn token_source_len(chars: &[char], start: usize, t: &Tok) -> usize {
    let s: String = chars[start..].iter().collect();
    match t {
        Tok::Delim { count, .. } => *count,
        Tok::OpenBracket { image, .. } => {
            if *image {
                2
            } else {
                1
            }
        }
        Tok::CloseBracket => 1,
        Tok::Node(Node::SoftBreak) | Tok::Node(Node::HardBreak) => {
            // consumes trailing spaces before newline (already removed from text), the
            // newline and leading spaces of the next line
            let mut n = 0;
            let cs = &chars[start..];
            while n < cs.len() && cs[n] == ' ' {
                n += 1;
            }
            if n < cs.len() && cs[n] == '\\' {
                n += 1;
            }
            if n < cs.len() && cs[n] == '\n' {
                n += 1;
            }
            while n < cs.len() && cs[n] == ' ' {
                n += 1;
            }
            n
        }
        Tok::Node(Node::Code(_)) => {
            scan_code_span(&s).map(|(_, l)| s[..l].chars().count()).unwrap_or(1)
        }
        Tok::Node(Node::Html(h)) => h.chars().count(),
        Tok::Node(Node::Link { .. }) => {
            // autolink
            scan_autolink(&s).map(|(_, _, l)| s[..l].chars().count()).unwrap_or(1)
        }
        Tok::Node(Node::Text(txt)) => {
            // Text may have come from escapes/entities; walk source matching decoded chars
            let mut n = 0;
            let cs = &chars[start..];
            let mut produced = String::new();
            while produced.chars().count() < txt.chars().count() && n < cs.len() {
                let c = cs[n];
                if c == '\\' && n + 1 < cs.len() && is_ascii_punct(cs[n + 1]) {
                    produced.push(cs[n + 1]);
                    n += 2;
                } else if c == '&' {
                    let rest: String = cs[n + 1..].iter().collect();
                    if let Some((decoded, len)) = parse_entity(&rest) {
                        produced.push_str(&decoded);
                        n += 1 + len;
                    } else {
                        produced.push('&');
                        n += 1;
                    }
                } else {
                    produced.push(c);
                    n += 1;
                }
            }
            n
        }
        Tok::Node(_) => 0,
    }
}

fn process_emphasis(toks: &mut Vec<Tok>) {
    // Standard CommonMark delimiter algorithm (simplified openers_bottom).
    let mut closer_idx = 0;
    while closer_idx < toks.len() {
        let (ch, can_close) = match &toks[closer_idx] {
            Tok::Delim { ch, can_close, active, .. } if *active => (*ch, *can_close),
            _ => {
                closer_idx += 1;
                continue;
            }
        };
        if !can_close {
            closer_idx += 1;
            continue;
        }
        // look back for opener
        let mut opener_idx = None;
        let closer_count = match &toks[closer_idx] {
            Tok::Delim { count, .. } => *count,
            _ => 0,
        };
        let closer_can_open = match &toks[closer_idx] {
            Tok::Delim { can_open, .. } => *can_open,
            _ => false,
        };
        let mut j = closer_idx;
        while j > 0 {
            j -= 1;
            if let Tok::Delim { ch: och, count: ocount, can_open: ocan_open, can_close: ocan_close, active: oactive } = &toks[j] {
                if !*oactive || *och != ch || !*ocan_open {
                    continue;
                }
                // rule of 3
                if (*ocan_close || closer_can_open) && (ocount + closer_count) % 3 == 0 && !(ocount % 3 == 0 && closer_count % 3 == 0) {
                    continue;
                }
                if ch == '~' && *ocount != closer_count {
                    continue;
                }
                opener_idx = Some(j);
                break;
            }
        }
        let Some(oi) = opener_idx else {
            closer_idx += 1;
            continue;
        };
        let ocount = match &toks[oi] {
            Tok::Delim { count, .. } => *count,
            _ => 0,
        };
        let use_n = if ch == '~' { ocount } else if ocount >= 2 && closer_count >= 2 { 2 } else { 1 };
        // Build the wrapped node from tokens between opener and closer
        let inner: Vec<Tok> = toks.drain(oi + 1..closer_idx).collect();
        let inner_nodes: Vec<Node> = inner
            .into_iter()
            .map(|t| match t {
                Tok::Node(n) => n,
                Tok::Delim { ch, count, .. } => Node::Text(std::iter::repeat(ch).take(count).collect()),
                Tok::OpenBracket { image, .. } => Node::Text(if image { "![".into() } else { "[".into() }),
                Tok::CloseBracket => Node::Text("]".into()),
            })
            .collect();
        let node = match (ch, use_n) {
            ('~', _) => Node::Strike(inner_nodes),
            (_, 2) => Node::Strong(inner_nodes),
            _ => Node::Emph(inner_nodes),
        };
        let closer_new_idx = oi + 1;
        // adjust counts
        let mut remove_opener = false;
        let mut remove_closer = false;
        if let Tok::Delim { count, .. } = &mut toks[oi] {
            *count -= use_n;
            if *count == 0 {
                remove_opener = true;
            }
        }
        if let Tok::Delim { count, .. } = &mut toks[closer_new_idx] {
            *count -= use_n;
            if *count == 0 {
                remove_closer = true;
            }
        }
        toks.insert(closer_new_idx, Tok::Node(node));
        let mut next_closer = closer_new_idx + 1;
        if remove_closer {
            toks.remove(next_closer);
        }
        if remove_opener {
            toks.remove(oi);
            next_closer -= 1;
        }
        closer_idx = if remove_closer { next_closer } else { next_closer };
    }
}

fn merge_text(nodes: &mut Vec<Node>) {
    let mut out: Vec<Node> = Vec::with_capacity(nodes.len());
    for n in nodes.drain(..) {
        let n = match n {
            Node::Emph(mut c) => {
                merge_text(&mut c);
                Node::Emph(c)
            }
            Node::Strong(mut c) => {
                merge_text(&mut c);
                Node::Strong(c)
            }
            Node::Strike(mut c) => {
                merge_text(&mut c);
                Node::Strike(c)
            }
            Node::Link { url, title, mut children } => {
                merge_text(&mut children);
                Node::Link { url, title, children }
            }
            Node::Image { url, title, mut alt } => {
                merge_text(&mut alt);
                Node::Image { url, title, alt }
            }
            other => other,
        };
        if let (Some(Node::Text(prev)), Node::Text(t)) = (out.last_mut(), &n) {
            prev.push_str(t);
            continue;
        }
        out.push(n);
    }
    *nodes = out;
}

/// Parse inline markdown into a node tree.
pub fn parse_inline(s: &str, refs: &RefDefs) -> Vec<Node> {
    InlineParser { refs }.parse(s)
}

/// Concatenate the text runs of an inline tree (mimicking "Text events only").
pub fn nodes_plain_text(nodes: &[Node], out: &mut String) {
    for n in nodes {
        match n {
            Node::Text(t) => out.push_str(t),
            Node::Code(_) | Node::Html(_) | Node::SoftBreak | Node::HardBreak => {}
            Node::Emph(c) | Node::Strong(c) | Node::Strike(c) => nodes_plain_text(c, out),
            Node::Link { children, .. } => nodes_plain_text(children, out),
            Node::Image { alt, .. } => nodes_plain_text(alt, out),
        }
    }
}

/// Plain text of an inline markdown string.
pub fn inline_plain_text(s: &str, refs: &RefDefs) -> String {
    let nodes = parse_inline(s, refs);
    let mut out = String::new();
    nodes_plain_text(&nodes, &mut out);
    out
}
