impl<'a> InlineParser<'a> {
    /// Single pass tokenizer that resolves links/images as soon as a closing
    /// bracket is seen (as cmark does).
    fn parse(&self, s: &str) -> Vec<Node> {
        let chars: Vec<char> = s.chars().collect();
        let mut toks: Vec<Tok> = Vec::new();
        // char position right after each token (used to recover label text)
        let mut tok_end: Vec<usize> = Vec::new();
        let mut text = String::new();
