                    flush!();
                    i += 2;
                    push_tok!(Tok::OpenBracket { image: true, active: true }, i);
                }
                '[' => {
                    flush!();
                    i += 1;
                    push_tok!(Tok::OpenBracket { image: false, active: true }, i);
                }
