        self.source.split_whitespace().count()
    }

    /// Offset of the start of the line following the heading's first line.
    pub fn heading_content_start(&self, idx: usize) -> usize {
        next_line_start(&self.source, self.headings[idx].offset)
    }

    /// End offset of the section (offset of the next heading with level <= this one).
    pub fn section_end(&self, idx: usize) -> usize {
        let level = self.headings[idx].level;
        for h in &self.headings[idx + 1..] {
            if h.level <= level {
                return h.offset;
            }
        }
        self.source.len()
    }

    /// Raw markdown of the section including the heading line.
    pub fn section_raw_md(&self, idx: usize) -> &str {
        &self.source[self.headings[idx].offset..self.section_end(idx)]
    }

    /// Section content (without heading line), trimmed.
    pub fn section_content(&self, idx: usize) -> &str {
        let start = self.heading_content_start(idx);
        let end = self.section_end(idx).max(start);
        self.source[start..end].trim()
    }

    /// Find a heading by (case-insensitive) exact text match.
    pub fn find_heading(&self, name: &str) -> Option<usize> {
        let lname = name.to_lowercase();
        self.headings.iter().position(|h| h.text.to_lowercase() == lname)
    }

    /// Section extraction as performed by `--section`: locates the heading by
    /// searching the source for the reconstructed heading line.
    pub fn extract_section_by_needle(&self, idx: usize) -> Option<String> {
        let h = &self.headings[idx];
        let needle = format!("{} {}", "#".repeat(h.level as usize), h.text);
        let start = self.source.find(&needle)?;
        let mut end = self.source.len();
        for next in &self.headings[idx + 1..] {
            if next.level <= h.level {
                let n2 = format!("{} {}", "#".repeat(next.level as usize), next.text);
                if let Some(pos) = self.source[start..].find(&n2) {
                    end = start + pos;
                }
                break;
            }
        }
        Some(self.source[start..end].trim().to_string())
    }

    /// Content range used by the JSON exporter: from the line after the heading
    /// up to the next ATX-looking line (outside of ``` fences), any level.
    pub fn json_section_range(&self, idx: usize) -> (usize, usize) {
        let start = self.heading_content_start(idx);
        let mut in_fence = false;
        let mut pos = start;
        for line in self.source[start..].split_inclusive('\n') {
            let t = line.trim_start();
            if t.starts_with("```") {
                in_fence = !in_fence;
            } else if !in_fence && is_atx_line(t) {
                return (start, pos);
            }
            pos += line.len();
        }
        (start, self.source.len())
    }
