/// Does a (left-trimmed) line look like an ATX heading (1-6 `#` followed by whitespace)?
pub fn is_atx_line(t: &str) -> bool {
    let hashes = t.bytes().take_while(|&b| b == b'#').count();
    if hashes == 0 || hashes > 6 {
        return false;
    }
    matches!(t.as_bytes().get(hashes), Some(b' ') | Some(b'\t'))
}

/// Tree of headings (children nested by level).
#[derive(Debug, Clone)]
pub struct HeadingNode {
    pub idx: usize,
    pub children: Vec<HeadingNode>,
}

pub fn build_tree(headings: &[Heading]) -> Vec<HeadingNode> {
    let mut roots: Vec<HeadingNode> = Vec::new();
    // stack of (level, path indices)
    let mut stack: Vec<(u8, Vec<usize>)> = Vec::new();
    for (i, h) in headings.iter().enumerate() {
        while let Some((lvl, _)) = stack.last() {
            if *lvl >= h.level {
                stack.pop();
            } else {
                break;
            }
        }
        let node = HeadingNode { idx: i, children: Vec::new() };
        let path = match stack.last() {
            None => {
                roots.push(node);
                vec![roots.len() - 1]
            }
            Some((_, parent_path)) => {
                let mut cur: &mut Vec<HeadingNode> = &mut roots;
                for &p in parent_path.iter() {
                    cur = &mut cur[p].children;
                }
                cur.push(node);
                let mut path = parent_path.clone();
                path.push(cur.len() - 1);
                path
            }
        };
        stack.push((h.level, path));
    }
    roots
}

pub fn tree_max_depth(nodes: &[HeadingNode]) -> usize {
    nodes
        .iter()
        .map(|n| 1 + tree_max_depth(&n.children))
        .max()
        .unwrap_or(0)
}

/// URL-friendly slug used for heading ids.
pub fn slugify(text: &str) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in text.chars() {
        let lower: Vec<char> = ch.to_lowercase().collect();
        for c in lower {
            if c.is_alphanumeric() {
                out.push(c);
                last_dash = false;
            } else if c.is_whitespace() || c == '-' {
                if !last_dash && !out.is_empty() {
                    out.push('-');
                    last_dash = true;
                }
            }
            // other punctuation removed
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}
