//! Non-interactive output modes: list, tree, count, section, JSON export.

use crate::md::document::{build_tree, slugify, tree_max_depth, Document, Heading, HeadingNode};
use serde_json::{json, Map, Value};

pub fn heading_line(h: &Heading) -> String {
    format!("{} {}", "#".repeat(h.level as usize), h.text)
}

/// Apply --level / --filter selection (level takes precedence).
pub fn select_headings<'a>(doc: &'a Document, level: Option<usize>, filter: Option<&str>) -> Vec<&'a Heading> {
    if let Some(l) = level {
        doc.headings.iter().filter(|h| h.level as usize == l).collect()
    } else if let Some(f) = filter {
        let f = f.to_lowercase();
        doc.headings.iter().filter(|h| h.text.to_lowercase().contains(&f)).collect()
    } else {
        doc.headings.iter().collect()
    }
}

pub fn print_list(doc: &Document, level: Option<usize>, filter: Option<&str>) {
    for h in select_headings(doc, level, filter) {
        println!("{}", heading_line(h));
    }
}

pub fn render_tree(doc: &Document) -> String {
    let roots = build_tree(&doc.headings);
    let mut out = String::new();
    fn walk(doc: &Document, nodes: &[HeadingNode], prefix: &str, out: &mut String) {
        let n = nodes.len();
        for (i, node) in nodes.iter().enumerate() {
            let last = i + 1 == n;
