//! Lightweight inline parser producing a flat list of inline elements, used
//! for the JSON export, element extraction (links) and content rendering.

use super::inline_text::{parse_entity, RefDefs};

#[derive(Debug, Clone, PartialEq)]
pub enum Inline {
    Text(String),
    Emphasis(String),
    Strong(String),
    Code(String),
    Strikethrough(String),
    Link { text: String, url: String },
    Image { alt: String, src: String },
}

impl Inline {
    pub fn type_name(&self) -> &'static str {
        match self {
            Inline::Text(_) => "text",
            Inline::Emphasis(_) => "emphasis",
            Inline::Strong(_) => "strong",
            Inline::Code(_) => "code",
            Inline::Strikethrough(_) => "strikethrough",
            Inline::Link { .. } => "link",
            Inline::Image { .. } => "image",
        }
    }

    /// Plain text of the element.
    pub fn text(&self) -> &str {
        match self {
            Inline::Text(s)
            | Inline::Emphasis(s)
            | Inline::Strong(s)
            | Inline::Code(s)
            | Inline::Strikethrough(s) => s,
            Inline::Link { text, .. } => text,
            Inline::Image { alt, .. } => alt,
        }
    }
}

/// Reconstruct the paragraph "content" string from inline elements.
/// (Images reset the accumulated content, mirroring the original behaviour.)
pub fn inline_content(nodes: &[Inline]) -> String {
    let mut out = String::new();
    for n in nodes {
        match n {
            Inline::Text(s)
            | Inline::Emphasis(s)
            | Inline::Strong(s)
            | Inline::Code(s)
            | Inline::Strikethrough(s) => out.push_str(s),
            Inline::Link { text, url } => out.push_str(&format!("[{}]({})", text, url)),
            Inline::Image { alt, src } => out = format!("![{}]({})", alt, src),
        }
    }
    out
}

/// Plain text (no markup) of a sequence of inline elements.
pub fn inline_plain(nodes: &[Inline]) -> String {
    let mut out = String::new();
    for n in nodes {
        match n {
            Inline::Link { text, .. } => out.push_str(text),
            Inline::Image { alt, .. } => out.push_str(alt),
            other => out.push_str(other.text()),
        }
    }
    out
}

fn find_matching(chars: &[char], start: usize, open: char, close: char) -> Option<usize> {
    // chars[start] == open; returns index of matching close
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c == open {
            depth += 1;
        } else if c == close {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

/// Find the closing delimiter `delim` (a run of `delim.len()` chars) starting
/// the search at `from`. The closer must not be preceded by whitespace and, for
/// single-character delimiters, must not be part of a longer run.
fn find_closer(chars: &[char], from: usize, delim: &[char]) -> Option<usize> {
    let n = delim.len();
    let mut i = from;
    while i + n <= chars.len() {
        if chars[i..i + n] == *delim {
            let prev_ws = i == 0 || chars[i - 1].is_whitespace();
            let longer_run = (i + n < chars.len() && chars[i + n] == delim[0])
                || (i > 0 && chars[i - 1] == delim[0]);
            if !prev_ws && (n > 1 || !longer_run) {
                return Some(i);
            }
            if n == 1 && longer_run {
                // skip the whole run
                let mut j = i;
                while j < chars.len() && chars[j] == delim[0] {
                    j += 1;
                }
                i = j;
                continue;
            }
        }
        i += 1;
    }
    None
}

struct Parser<'a> {
    refs: &'a RefDefs,
}

impl<'a> Parser<'a> {
    fn parse(&self, s: &str) -> Vec<Inline> {
        let chars: Vec<char> = s.chars().collect();
        let mut out: Vec<Inline> = Vec::new();
        let mut cur = String::new();
        let mut i = 0;

        macro_rules! flush {
            () => {
                if !cur.is_empty() {
                    out.push(Inline::Text(std::mem::take(&mut cur)));
                }
            };
        }

        while i < chars.len() {
            let c = chars[i];
            match c {
                '\\' => {
                    if i + 1 < chars.len() {
                        if chars[i + 1] == '\n' {
                            flush!();
                            out.push(Inline::Text("\n".into()));
                            i += 2;
                            while i < chars.len() && chars[i] == ' ' {
                                i += 1;
                            }
                        } else if chars[i + 1].is_ascii_punctuation() {
                            flush!();
                            cur.push(chars[i + 1]);
                            i += 2;
                        } else {
                            cur.push('\\');
                            i += 1;
                        }
                    } else {
                        cur.push('\\');
                        i += 1;
                    }
                }
                '`' => {
                    let n = chars[i..].iter().take_while(|&&x| x == '`').count();
                    // find closing run of the same length
                    let mut j = i + n;
                    let mut found = None;
                    while j < chars.len() {
                        if chars[j] == '`' {
                            let m = chars[j..].iter().take_while(|&&x| x == '`').count();
                            if m == n {
                                found = Some(j);
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                    if let Some(j) = found {
                        flush!();
                        let mut code: String = chars[i + n..j].iter().collect();
                        code = code.replace('\n', " ");
                        if code.len() >= 2 && code.starts_with(' ') && code.ends_with(' ') && !code.trim().is_empty() {
                            code = code[1..code.len() - 1].to_string();
                        }
                        out.push(Inline::Code(code));
                        i = j + n;
                    } else {
                        for _ in 0..n {
                            cur.push('`');
                        }
                        i += n;
                    }
                }
                '*' | '_' | '~' => {
                    let n = chars[i..].iter().take_while(|&&x| x == c).count();
                    let after = chars.get(i + n).copied();
                    let before = if i == 0 { None } else { Some(chars[i - 1]) };
                    let can_open = after.map(|a| !a.is_whitespace()).unwrap_or(false)
                        && (c != '_' || before.map(|b| !b.is_alphanumeric()).unwrap_or(true));
                    let mut handled = false;
                    if can_open {
                        // try longest sensible delimiter first
                        let candidates: Vec<usize> = if c == '~' {
                            if n >= 2 { vec![2, 1] } else { vec![1] }
                        } else if n >= 3 {
                            vec![3, 2, 1]
                        } else if n == 2 {
                            vec![2, 1]
                        } else {
                            vec![1]
                        };
                        for &len in &candidates {
                            let delim: Vec<char> = std::iter::repeat(c).take(len).collect();
                            let content_start = i + len;
                            if let Some(close) = find_closer(&chars, content_start + 1, &delim) {
                                if c == '_' {
                                    // closer must not be followed by alphanumeric
                                    if let Some(a) = chars.get(close + len) {
                                        if a.is_alphanumeric() {
                                            continue;
                                        }
                                    }
