                                if inner.is_empty() {
                                    continue;
                                }
                                flush!();
                                let inner_nodes = self.parse(&inner);
                                for node in inner_nodes {
                                    let wrapped = match node {
                                        Inline::Text(t) => match (c, len) {
                                            ('~', _) => Inline::Strikethrough(t),
                                            (_, 1) => Inline::Emphasis(t),
                                            _ => Inline::Strong(t),
                                        },
                                        other => other,
                                    };
