                                let src: String = chars[close + 2..pclose].iter().collect();
                                flush!();
                                let alt = inline_plain(&self.parse(&alt_raw));
                                out.push(Inline::Image { alt, src });
                                i = pclose + 1;
                                continue;
                            }
                        }
                    }
                    cur.push('!');
                    i += 1;
                }
                '[' => {
                    if let Some(close) = find_matching(&chars, i, '[', ']') {
                        let text_raw: String = chars[i + 1..close].iter().collect();
                        // inline link
                        if close + 1 < chars.len() && chars[close + 1] == '(' {
                            if let Some(pclose) = find_matching(&chars, close + 1, '(', ')') {
                                let url: String = chars[close + 2..pclose].iter().collect();
                                flush!();
                                let text = inline_plain(&self.parse(&text_raw));
                                out.push(Inline::Link { text, url });
                                i = pclose + 1;
                                continue;
                            }
