                }
                ']' => {
                    flush!();
                    out.push(Inline::Text("]".into()));
                    i += 1;
                }
                '<' => {
                    let rest: String = chars[i..].iter().collect();
                    if let Some((url, len)) = scan_autolink_simple(&rest) {
                        flush!();
                        out.push(Inline::Link { text: url.clone(), url });
