                    if let Some((decoded, len)) = parse_entity(&rest) {
                        flush!();
                        out.push(Inline::Text(decoded));
                        i += 1 + len;
                    } else {
                        cur.push('&');
                        i += 1;
                    }
                }
                '\n' => {
                    let trailing = cur.len() - cur.trim_end_matches(' ').len();
                    let hard = trailing >= 2;
                    cur.truncate(cur.len() - trailing);
                    flush!();
                    out.push(Inline::Text(if hard { "\n".into() } else { " ".into() }));
                    i += 1;
                    while i < chars.len() && chars[i] == ' ' {
                        i += 1;
                    }
                }
                _ => {
                    cur.push(c);
                    i += 1;
                }
            }
        }
        flush!();
        out
    }
}

fn scan_autolink_simple(s: &str) -> Option<(String, usize)> {
    // s starts with '<'; returns (url, chars consumed)
    let end = s.find('>')?;
    let inner = &s[1..end];
    if inner.is_empty() || inner.contains(char::is_whitespace) || inner.contains('<') {
        return None;
    }
    let is_scheme = inner
        .find(':')
        .map(|c| {
            let scheme = &inner[..c];
            scheme.len() >= 2
                && scheme.chars().next().map(|ch| ch.is_ascii_alphabetic()).unwrap_or(false)
                && scheme.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '+' || ch == '.' || ch == '-')
        })
        .unwrap_or(false);
    let is_email = inner.contains('@')
        && !inner.starts_with('@')
        && !inner.ends_with('@')
        && inner.rsplit('@').next().map(|d| d.contains('.')).unwrap_or(false);
    if is_scheme || is_email {
        Some((inner.to_string(), s[..end + 1].chars().count()))
    } else {
        None
    }
}

fn scan_tag_simple(s: &str) -> Option<usize> {
    // s starts with '<'
    if s.starts_with("<!--") {
        return s.find("-->").map(|i| s[..i + 3].chars().count());
    }
    let b = s.as_bytes();
    if b.len() < 3 {
        return None;
    }
    let mut i = 1;
    if b[i] == b'/' {
        i += 1;
    }
    if i >= b.len() || !b[i].is_ascii_alphabetic() {
        return None;
    }
    let end = s.find('>')?;
    if s[..end].contains('\n') {
        return None;
    }
    Some(s[..end + 1].chars().count())
}

pub fn parse_inline(s: &str, refs: &RefDefs) -> Vec<Inline> {
    Parser { refs }.parse(s)
}
