            | Inline::Emphasis(s)
            | Inline::Strong(s)
            | Inline::Code(s)
            | Inline::Strikethrough(s) => s,
            Inline::Link { text, .. } => text,
            Inline::Image { alt, .. } => alt,
        }
    }
