/// Reconstruct the paragraph "content" string from inline elements.
/// (Images reset the accumulated content, mirroring the original behaviour.)
pub fn inline_content(nodes: &[Inline]) -> String {
    let mut out = String::new();
    for n in nodes {
        match n {
            Inline::Text(s)
            | Inline::Emphasis(s)
            | Inline::Strong(s)
            | Inline::Code(s)
            | Inline::Strikethrough(s) => out.push_str(s),
            Inline::Link { text, url } => out.push_str(&format!("[{}]({})", text, url)),
            Inline::Image { alt, src } => out = format!("![{}]({})", alt, src),
        }
    }
    out
}

/// Plain text (no markup) of a sequence of inline elements.
pub fn inline_plain(nodes: &[Inline]) -> String {
    let mut out = String::new();
    for n in nodes {
        match n {
            Inline::Link { text, .. } => out.push_str(text),
            Inline::Image { alt, .. } => out.push_str(alt),
            other => out.push_str(other.text()),
        }
    }
    out
}

fn find_matching(chars: &[char], start: usize, open: char, close: char) -> Option<usize> {
    // chars[start] == open; returns index of matching close
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c == open {
            depth += 1;
        } else if c == close {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

/// Find the closing delimiter `delim` (a run of `delim.len()` chars) starting
/// the search at `from`. The closer must not be preceded by whitespace and, for
/// single-character delimiters, must not be part of a longer run.
fn find_closer(chars: &[char], from: usize, delim: &[char]) -> Option<usize> {
    let n = delim.len();
    let mut i = from;
    while i + n <= chars.len() {
        if chars[i..i + n] == *delim {
            let prev_ws = i == 0 || chars[i - 1].is_whitespace();
            let longer_run = (i + n < chars.len() && chars[i + n] == delim[0])
