            if !prev_ws && (n > 1 || !longer_run) {
                return Some(i);
            }
            if n == 1 && longer_run {
                // skip the whole run
                let mut j = i;
                while j < chars.len() && chars[j] == delim[0] {
                    j += 1;
                }
                i = j;
                continue;
            }
        }
        i += 1;
    }
    None
}

