}

fn leading_spaces(s: &str) -> usize {
    s.chars().take_while(|c| *c == ' ' || *c == '\t').map(|c| if c == '\t' { 4 } else { 1 }).sum()
}

/// Fence opener: returns (fence char, length, info string).
fn fence_open(line: &str) -> Option<(char, usize, String)> {
    let t = line.trim_start();
    if leading_spaces(line) > 3 {
        return None;
    }
    let first = t.chars().next()?;
    if first != '`' && first != '~' {
        return None;
    }
    let len = t.chars().take_while(|&c| c == first).count();
    if len < 3 {
        return None;
    }
    let info = t[len..].trim().to_string();
    if first == '`' && info.contains('`') {
        return None;
    }
    Some((first, len, info))
}

fn fence_close(line: &str, ch: char, len: usize) -> bool {
    let t = line.trim();
    let n = t.chars().take_while(|&c| c == ch).count();
    n >= len && t[n..].trim().is_empty() && leading_spaces(line) <= 3
}

/// List marker: returns (marker length incl. following space, ordered, number)
pub fn list_marker(t: &str) -> Option<(usize, bool, u64)> {
    let b = t.as_bytes();
    if b.is_empty() {
        return None;
    }
    if (b[0] == b'-' || b[0] == b'*' || b[0] == b'+') && b.len() >= 2 && (b[1] == b' ' || b[1] == b'\t') {
        return Some((2, false, 0));
    }
    let digits = b.iter().take_while(|c| c.is_ascii_digit()).count();
    if digits > 0 && digits <= 9 && digits + 1 < b.len() {
        if (b[digits] == b'.' || b[digits] == b')') && (b[digits + 1] == b' ' || b[digits + 1] == b'\t') {
            let n: u64 = t[..digits].parse().unwrap_or(0);
            return Some((digits + 2, true, n));
        }
    }
    None
}

fn is_hr(t: &str) -> bool {
    let t = t.trim();
    let first = match t.chars().next() {
        Some(c @ ('-' | '*' | '_')) => c,
        _ => return false,
    };
    let mut count = 0;
    for c in t.chars() {
        if c == first {
            count += 1;
        } else if c != ' ' {
            return false;
        }
    }
    count >= 3
}

fn is_table_separator(t: &str) -> bool {
    let t = t.trim();
    if !t.contains('-') {
        return false;
    }
    let inner = t.trim_start_matches('|').trim_end_matches('|');
    if inner.is_empty() {
        return false;
    }
    inner.split('|').all(|cell| {
        let c = cell.trim();
        !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':') && c.contains('-')
    })
}

fn split_table_row(t: &str) -> Vec<String> {
    let mut t = t.trim();
    if t.starts_with('|') {
        t = &t[1..];
    }
    if t.ends_with('|') && !t.ends_with("\\|") {
        t = &t[..t.len() - 1];
    }
    // split on unescaped pipes
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut chars = t.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if n == '|' {
                    cur.push('|');
                    chars.next();
                    continue;
                }
            }
            cur.push(c);
        } else if c == '|' {
            cells.push(cur.trim().to_string());
            cur = String::new();
        } else {
            cur.push(c);
        }
    }
    cells.push(cur.trim().to_string());
    cells
}

fn alignment_of(cell: &str) -> &'static str {
    let c = cell.trim();
    let left = c.starts_with(':');
    let right = c.ends_with(':');
    match (left, right) {
        (true, true) => "center",
        (true, false) => "left",
        (false, true) => "right",
        _ => "none",
    }
}

fn strip_quote_prefix(line: &str) -> &str {
    let mut s = line.trim_start();
    while let Some(rest) = s.strip_prefix('>') {
        s = rest.strip_prefix(' ').unwrap_or(rest);
        s = s.trim_start_matches(|c: char| c == ' ' && false);
        let t = s.trim_start();
        if t.starts_with('>') {
            s = t;
        } else {
            break;
        }
    }
    s
}

fn is_html_block_start(t: &str) -> bool {
    let b = t.as_bytes();
    if b.len() < 2 || b[0] != b'<' {
        return false;
    }
    b[1].is_ascii_alphabetic() || b[1] == b'/' || b[1] == b'!' || b[1] == b'?'
}

pub struct BlockParser<'a> {
    refs: &'a RefDefs,
}

impl<'a> BlockParser<'a> {
    fn parse(&self, text: &str) -> Vec<Block> {
        let lines: Vec<&str> = text.lines().collect();
        let mut blocks = Vec::new();
        let mut i = 0;
        while i < lines.len() {
            let line = lines[i];
            let t = line.trim_start();

            if is_blank(line) {
                i += 1;
                continue;
            }

            // fenced code
            if let Some((ch, len, info)) = fence_open(line) {
                let mut j = i + 1;
                let mut content = Vec::new();
                let mut closed = false;
                while j < lines.len() {
                    if fence_close(lines[j], ch, len) {
                        closed = true;
                        break;
                    }
                    content.push(lines[j]);
                    j += 1;
                }
                if closed || ch == '`' || !content.is_empty() {
                    blocks.push(Block::Code {
                        language: if info.is_empty() { None } else { Some(info) },
                        content: content.join("\n"),
                    });
                    i = if closed { j + 1 } else { j };
                    continue;
                }
            }

            // indented code (only when not continuing a paragraph)
            if leading_spaces(line) >= 4 {
                let mut j = i;
                let mut content: Vec<String> = Vec::new();
                while j < lines.len() && (leading_spaces(lines[j]) >= 4 || is_blank(lines[j])) {
                    if is_blank(lines[j]) {
                        // only include blank lines if followed by more indented code
                        let mut k = j;
                        while k < lines.len() && is_blank(lines[k]) {
                            k += 1;
                        }
                        if k < lines.len() && leading_spaces(lines[k]) >= 4 {
                            for _ in j..k {
                                content.push(String::new());
                            }
                            j = k;
                            continue;
                        }
                        break;
                    }
                    content.push(dedent(lines[j], 4));
                    j += 1;
                }
                blocks.push(Block::Code { language: None, content: content.join("\n") });
                i = j;
                continue;
            }

            // ATX heading
            if let Some((level, _idx, raw)) = atx_heading(line) {
                let raw_text = strip_closing_hashes(raw).to_string();
                let inline = parse_inline(&raw_text, self.refs);
                blocks.push(Block::Heading { level, text: raw_text, inline });
                i += 1;
                continue;
            }

            // horizontal rule
            if is_hr(t) {
                blocks.push(Block::HorizontalRule);
                i += 1;
                continue;
            }

            // block quote
            if t.starts_with('>') {
                let mut j = i;
                let mut inner_lines: Vec<String> = Vec::new();
                while j < lines.len() && lines[j].trim_start().starts_with('>') {
                    inner_lines.push(strip_quote_prefix(lines[j]).to_string());
                    j += 1;
                }
                // hoist fenced code blocks out of the quote
                let mut text_parts: Vec<String> = Vec::new();
                let mut k = 0;
                while k < inner_lines.len() {
                    if let Some((ch, len, info)) = fence_open(&inner_lines[k]) {
                        let mut m = k + 1;
                        let mut content = Vec::new();
                        while m < inner_lines.len() && !fence_close(&inner_lines[m], ch, len) {
                            content.push(inner_lines[m].clone());
                            m += 1;
                        }
                        blocks.push(Block::Code {
                            language: if info.is_empty() { None } else { Some(info) },
                            content: content.join("\n"),
                        });
                        k = m + 1;
                        continue;
                    }
                    if inner_lines[k].trim().is_empty() {
                        blocks.push(Block::Paragraph { inline: vec![Inline::Text(" ".into())] });
                    } else {
                        text_parts.push(inner_lines[k].trim().to_string());
                    }
                    k += 1;
                }
                let joined = text_parts.join("");
                let inline = parse_inline(&joined, self.refs);
                let inner_blocks = if inline.is_empty() {
                    vec![]
                } else {
                    vec![Block::Paragraph { inline: inline.clone() }]
                };
                blocks.push(Block::BlockQuote { inline, blocks: inner_blocks });
                i = j;
                continue;
            }

            // list
            if let Some((_mlen, ordered, start_num)) = list_marker(t) {
                let (items, next) = self.parse_list(&lines, i, ordered, t.as_bytes()[0]);
                blocks.push(Block::List { ordered, items, start: start_num });
                i = next;
                continue;
            }

            // table
            if i + 1 < lines.len() && line.contains('|') && is_table_separator(lines[i + 1]) {
                let headers_raw = split_table_row(line);
                let headers: Vec<String> = headers_raw.iter().map(|h| self.cell_text(h)).collect();
                let aligns: Vec<String> = split_table_row(lines[i + 1]).iter().map(|c| alignment_of(c).to_string()).collect();
                let mut alignments = aligns;
                alignments.resize(headers.len(), "none".to_string());
                let mut rows = Vec::new();
                let mut j = i + 2;
                while j < lines.len() && !is_blank(lines[j]) && lines[j].contains('|') {
                    let mut cells: Vec<String> = split_table_row(lines[j]).iter().map(|c| self.cell_text(c)).collect();
                    cells.resize(headers.len(), String::new());
                    rows.push(cells);
                    j += 1;
                }
                blocks.push(Block::Table { headers, alignments, rows });
                i = j;
                continue;
            }

            // html block
            if is_html_block_start(t) {
                let mut j = i;
                let mut hl = Vec::new();
                while j < lines.len() && !is_blank(lines[j]) {
                    hl.push(lines[j].to_string());
                    j += 1;
                }
                blocks.push(Block::Html { lines: hl });
                i = j;
                continue;
            }

            // paragraph (with setext detection)
            let mut j = i;
            let mut para: Vec<&str> = Vec::new();
            while j < lines.len() {
                let l = lines[j];
                if is_blank(l) {
                    break;
                }
                let lt = l.trim_start();
                if j > i {
                    // setext underline?
                    let tt = l.trim();
                    if !tt.is_empty() && leading_spaces(l) <= 3 {
                        if tt.chars().all(|c| c == '=') {
                            let text = para.join("\n");
                            let inline = parse_inline(&text, self.refs);
                            blocks.push(Block::Heading { level: 1, text, inline });
                            para.clear();
                            j += 1;
                            break;
                        }
                        if tt.chars().all(|c| c == '-') {
                            let text = para.join("\n");
                            let inline = parse_inline(&text, self.refs);
                            blocks.push(Block::Heading { level: 2, text, inline });
                            para.clear();
                            j += 1;
                            break;
                        }
                    }
                    if fence_open(l).is_some()
                        || atx_heading(l).is_some()
                        || lt.starts_with('>')
                        || is_hr(lt)
                        || list_marker(lt).map(|(_, o, n)| !o || n == 1).unwrap_or(false)
                        || (l.contains('|') && j + 1 < lines.len() && is_table_separator(lines[j + 1]))
                    {
                        break;
                    }
                }
                para.push(l.trim());
                j += 1;
            }
            if !para.is_empty() {
                let text = para.join("\n");
                let inline = parse_inline(&text, self.refs);
                blocks.push(Block::Paragraph { inline });
            }
            i = j.max(i + 1);
        }
        blocks
    }

    fn cell_text(&self, raw: &str) -> String {
        inline_content(&parse_inline(raw, self.refs))
    }

    /// Parse a list starting at `start`. Returns items and the next line index.
    fn parse_list(&self, lines: &[&str], start: usize, ordered: bool, marker_char: u8) -> (Vec<ListItem>, usize) {
        let mut items = Vec::new();
        let mut i = start;
        let base_indent = leading_spaces(lines[start]);
        while i < lines.len() {
            let line = lines[i];
            if is_blank(line) {
                // a blank line followed by another item of the same list continues
                let mut k = i;
                while k < lines.len() && is_blank(lines[k]) {
                    k += 1;
                }
                if k < lines.len() {
                    let nt = lines[k].trim_start();
                    let ind = leading_spaces(lines[k]);
                    if ind == base_indent {
                        if let Some((_, o, _)) = list_marker(nt) {
                            if o == ordered && (ordered || nt.as_bytes()[0] == marker_char) {
                                i = k;
                                continue;
                            }
                        }
                    }
                    if ind > base_indent && !items.is_empty() {
                        // continuation content of the last item
                        i = k;
                        // fallthrough to continuation handling below
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            let line = lines[i];
            let indent = leading_spaces(line);
            let t = line.trim_start();
            if indent == base_indent {
                if let Some((mlen, o, _n)) = list_marker(t) {
                    if o != ordered || (!ordered && t.as_bytes()[0] != marker_char) {
                        break;
                    }
                    // new item
                    let mut first = t[mlen..].to_string();
                    let mut checked = None;
                    let ft = first.trim_start();
                    if let Some(rest) = ft.strip_prefix("[ ]") {
                        if rest.is_empty() || rest.starts_with(' ') {
                            checked = Some(false);
                            first = rest.trim_start().to_string();
                        }
                    } else if let Some(rest) = ft.strip_prefix("[x]").or_else(|| ft.strip_prefix("[X]")) {
                        if rest.is_empty() || rest.starts_with(' ') {
                            checked = Some(true);
                            first = rest.trim_start().to_string();
                        }
                    }
                    items.push(ListItem {
                        content: String::new(),
                        checked,
                        inline: Vec::new(),
                        blocks: Vec::new(),
                        depth: 0,
                        raw_lines: vec![first],
                    });
                    i += 1;
                    continue;
                }
                break;
            }
            if indent > base_indent && !items.is_empty() {
                // continuation of the last item
                let item = items.last_mut().unwrap();
                let rel = dedent(line, base_indent + 2);
                let relt = rel.trim_start();
                if let Some((ch, len, info)) = fence_open(&rel) {
                    let mut j = i + 1;
                    let mut content = Vec::new();
                    while j < lines.len() {
                        let dl = dedent(lines[j], base_indent + 2);
                        if fence_close(&dl, ch, len) {
                            break;
                        }
                        content.push(dl);
                        j += 1;
                    }
                    item.blocks.push(Block::Code {
                        language: if info.is_empty() { None } else { Some(info) },
                        content: content.join("\n"),
                    });
                    i = j + 1;
                    continue;
                }
                if let Some((mlen, _o, _n)) = list_marker(relt) {
                    // nested list item: strip marker, keep indentation
                    let ws = &rel[..rel.len() - relt.len()];
                    let mut rest = relt[mlen..].to_string();
                    let rt = rest.trim_start();
                    if let Some(r) = rt.strip_prefix("[ ]").or_else(|| rt.strip_prefix("[x]")).or_else(|| rt.strip_prefix("[X]")) {
                        if r.is_empty() || r.starts_with(' ') {
                            rest = r.trim_start().to_string();
                        }
                    }
                    item.raw_lines.push(format!("{}{}", ws, rest));
                    i += 1;
                    continue;
                }
                item.raw_lines.push(rel);
                i += 1;
                continue;
            }
            break;
        }
        for item in items.iter_mut() {
            self.finish_item(item);
        }
        (items, i)
    }

    fn finish_item(&self, item: &mut ListItem) {
        // Plain continuation lines are joined and parsed once; nested item lines
        // (those starting with whitespace) are parsed separately.
        let mut plain: Vec<&str> = Vec::new();
        let mut nested: Vec<&str> = Vec::new();
        for (idx, l) in item.raw_lines.iter().enumerate() {
            if idx > 0 && l.starts_with(' ') {
                nested.push(l);
            } else if nested.is_empty() {
                plain.push(l);
            } else {
                nested.push(l);
            }
        }
        let text = plain.join("\n");
        let mut inline = parse_inline(&text, self.refs);
        let mut content = inline_content(&inline);
        for n in &nested {
            let parsed = parse_inline(n.trim(), self.refs);
            inline.extend(parsed);
            content.push('\n');
            content.push_str(n);
        }
        item.inline = inline;
        item.content = content;
    }
}

fn dedent(line: &str, n: usize) -> String {
    let mut removed = 0;
    let mut idx = 0;
    for (i, c) in line.char_indices() {
        if removed >= n {
            idx = i;
            break;
        }
        match c {
            ' ' => removed += 1,
            '\t' => removed += 4,
            _ => {
                idx = i;
                break;
            }
        }
        idx = i + c.len_utf8();
    }
    line[idx..].to_string()
}

pub fn parse_blocks(text: &str, refs: &RefDefs) -> Vec<Block> {
    BlockParser { refs }.parse(text)
}

pub fn inline_to_json(nodes: &[Inline], in_list: bool) -> Vec<Value> {
    nodes
        .iter()
        .map(|n| match n {
            Inline::Link { text, url } => {
                let mut m = Map::new();
                m.insert("type".into(), json!("link"));
                m.insert("text".into(), json!(text));
                m.insert("url".into(), json!(url));
                m.insert("title".into(), Value::Null);
                if in_list {
                    m.insert("line_offset".into(), json!(0));
                }
                Value::Object(m)
            }
            Inline::Image { alt, src } => json!({"type": "image", "alt": alt, "src": src, "title": Value::Null}),
            other => json!({"type": other.type_name(), "value": other.text()}),
        })
        .collect()
}

pub fn block_to_json(block: &Block, line: usize) -> Value {
    match block {
        Block::Heading { level, inline, text } => {
            let content = inline_content(inline);
            json!({
                "type": "heading",
                "level": level,
                "content": content,
                "inline": inline_to_json(inline, false),
                "anchor": super::document::slugify(&super::inline::inline_plain(inline)),
            })
            .tap_text(text)
        }
        Block::Paragraph { inline } => json!({
            "type": "paragraph",
            "content": inline_content(inline),
            "inline": inline_to_json(inline, false),
        }),
        Block::Code { language, content } => json!({
            "type": "code",
            "language": language,
            "content": content,
            "start_line": line,
            "end_line": line,
        }),
        Block::List { ordered, items, .. } => json!({
            "type": "list",
            "ordered": ordered,
            "items": items.iter().map(|it| {
                let mut m = Map::new();
                m.insert("checked".into(), json!(it.checked));
                m.insert("content".into(), json!(it.content));
                m.insert("inline".into(), Value::Array(inline_to_json(&it.inline, true)));
                if !it.blocks.is_empty() {
                    m.insert("blocks".into(), Value::Array(it.blocks.iter().map(|b| block_to_json(b, line)).collect()));
                }
                Value::Object(m)
            }).collect::<Vec<_>>(),
        }),
        Block::Table { headers, alignments, rows } => json!({
            "type": "table",
            "headers": headers,
            "alignments": alignments,
            "rows": rows,
        }),
        Block::BlockQuote { inline, blocks } => json!({
            "type": "blockquote",
            "content": inline_content(inline),
            "blocks": blocks.iter().map(|b| block_to_json(b, line)).collect::<Vec<_>>(),
        }),
        Block::HorizontalRule => json!({"type": "horizontalrule"}),
        Block::Html { .. } => json!({
            "type": "paragraph",
            "content": " ",
            "inline": [{"type": "text", "value": " "}],
        }),
    }
}

trait TapText {
    fn tap_text(self, text: &str) -> Value;
}
impl TapText for Value {
    fn tap_text(self, _text: &str) -> Value {
        self
    }
}
