//! Query error type and rendering.

#[derive(Debug, Clone)]
pub struct QueryError {
    pub message: String,
    /// Optional source span (char offsets) and label.
    pub span: Option<(usize, usize, String)>,
    /// Optional "did you mean" suggestions.
    pub suggestions: Vec<String>,
}

impl QueryError {
    pub fn new(message: impl Into<String>) -> Self {
        QueryError { message: message.into(), span: None, suggestions: Vec::new() }
    }

    pub fn spanned(message: impl Into<String>, start: usize, end: usize, label: &str) -> Self {
        QueryError { message: message.into(), span: Some((start, end, label.to_string())), suggestions: Vec::new() }
    }

    pub fn with_suggestions(mut self, s: Vec<String>) -> Self {
        self.suggestions = s;
        self
    }

    /// Render the error the way the CLI prints it (to stderr).
    pub fn render(&self, query: &str) -> String {
        let mut out = String::new();
        out.push_str(&format!("error: {}\n", self.message));
        if let Some((start, end, label)) = &self.span {
            out.push_str("  --> query\n");
            out.push_str("  |\n");
            out.push_str(&format!("1 | {}\n", query));
            let width = end.saturating_sub(*start).max(1);
            out.push_str(&format!("{}{}  {}\n", " ".repeat(4 + start), "^".repeat(width), label));
        } else if !self.suggestions.is_empty() {
            out.push_str("  |\n");
            let joined = self
                .suggestions
                .iter()
                .map(|s| format!("'{}'", s))
                .collect::<Vec<_>>()
                .join(" or ");
            out.push_str(&format!("  = help: did you mean {}?\n", joined));
        }
        out.push('\n');
        out
    }
}
