//! Recursive descent parser for the query language.

use super::ast::*;
use super::error::QueryError;
use super::lexer::{Tok, Token};
use super::value::Value;

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(toks: Vec<Token>) -> Self {
        Parser { toks, pos: 0 }
    }

    fn peek(&self) -> &Token {
        &self.toks[self.pos.min(self.toks.len() - 1)]
    }

    fn peek_tok(&self) -> &Tok {
        &self.peek().tok
    }

    fn peek_at(&self, n: usize) -> &Tok {
        &self.toks[(self.pos + n).min(self.toks.len() - 1)].tok
    }

    fn advance(&mut self) -> Token {
        let t = self.peek().clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn unexpected(&self, expected: &str) -> QueryError {
        let t = self.peek();
        QueryError::spanned(
            format!("Expected {}, found {}", expected, t.tok.describe()),
            t.start,
            t.end,
            "unexpected token",
        )
    }

    fn expect(&mut self, tok: Tok, desc: &str) -> Result<Token, QueryError> {
        if *self.peek_tok() == tok {
            Ok(self.advance())
        } else {
            Err(self.unexpected(desc))
        }
    }

    pub fn parse_query(&mut self) -> Result<Expr, QueryError> {
        let e = self.parse_pipe()?;
        if *self.peek_tok() != Tok::Eof {
            return Err(self.unexpected("end of query"));
        }
        Ok(e)
    }

    fn parse_pipe(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_or()?;
        while *self.peek_tok() == Tok::Pipe {
            self.advance();
            let rhs = self.parse_or()?;
            lhs = Expr::Pipe(Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_or(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_and()?;
        while *self.peek_tok() == Tok::KwOr {
            self.advance();
            let rhs = self.parse_and()?;
            lhs = Expr::Binary { op: BinOp::Or, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_and(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_comparison()?;
        while *self.peek_tok() == Tok::KwAnd {
            self.advance();
            let rhs = self.parse_comparison()?;
            lhs = Expr::Binary { op: BinOp::And, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_comparison(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_additive()?;
        loop {
            let op = match self.peek_tok() {
                Tok::EqEq => BinOp::Eq,
                Tok::NotEq => BinOp::Ne,
                Tok::Lt => BinOp::Lt,
                Tok::Le => BinOp::Le,
                Tok::Ge => BinOp::Ge,
                Tok::Gt | Tok::GtGt => {
                    let direct = *self.peek_tok() == Tok::Gt;
                    if *self.peek_at(1) == Tok::Dot || !direct {
                        self.advance();
                        let child = self.parse_additive()?;
                        lhs = Expr::Child { parent: Box::new(lhs), child: Box::new(child), direct };
                        continue;
                    }
                    BinOp::Gt
                }
                _ => break,
            };
            self.advance();
            let rhs = self.parse_additive()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_additive(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_multiplicative()?;
        loop {
            let op = match self.peek_tok() {
                Tok::Plus => BinOp::Add,
                Tok::Minus => BinOp::Sub,
                _ => break,
            };
            self.advance();
            let rhs = self.parse_multiplicative()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_unary()?;
        loop {
            let op = match self.peek_tok() {
                Tok::Star => BinOp::Mul,
                Tok::Slash => BinOp::Div,
                Tok::Percent => BinOp::Mod,
                _ => break,
            };
            self.advance();
            let rhs = self.parse_unary()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_unary(&mut self) -> Result<Expr, QueryError> {
        match self.peek_tok() {
            Tok::KwNot => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Not(Box::new(e)))
            }
            Tok::Minus => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Neg(Box::new(e)))
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Result<Expr, QueryError> {
        let mut e = self.parse_primary()?;
        loop {
            match self.peek_tok() {
                Tok::LBracket => {
                    self.advance();
                    let (filter, index) = self.parse_filter()?;
                    if let Expr::Selector { filter: f, index: i, .. } = &mut e {
                        if filter.is_some() {
                            *f = filter;
                        }
                        if index.is_some() {
                            *i = index;
                        }
                    }
                }
                Tok::Dot => {
                    // `.ident` after an expression replaces it with a property access
                    self.advance();
                    match self.peek_tok().clone() {
                        Tok::Ident(name) => {
                            self.advance();
                            e = Expr::Field(name);
                        }
                        _ => return Err(self.unexpected("identifier")),
                    }
                }
                _ => break,
            }
        }
        Ok(e)
    }

    /// Parse the inside of `[...]` (after the opening bracket), consuming `]`.
    fn parse_filter(&mut self) -> Result<(Option<TextFilter>, Option<IndexSpec>), QueryError> {
        let t = self.peek().clone();
        match &t.tok {
            Tok::RBracket => {
                self.advance();
                Ok((None, None))
            }
            Tok::Str(s) => {
                let s = s.clone();
                self.advance();
                self.expect(Tok::RBracket, "']'")?;
                Ok((Some(TextFilter { pattern: s, exact: true }), None))
            }
            Tok::Ident(name) => {
                let name = name.clone();
                self.advance();
                self.expect(Tok::RBracket, "']'")?;
                Ok((Some(TextFilter { pattern: name, exact: false }), None))
            }
            Tok::Number(_) | Tok::Minus | Tok::Colon => {
                // index or slice
                let start = self.parse_opt_int()?;
                if *self.peek_tok() == Tok::Colon {
                    self.advance();
                    let end = self.parse_opt_int()?;
                    self.expect(Tok::RBracket, "']'")?;
                    Ok((None, Some(IndexSpec::Slice(start, end))))
                } else {
                    self.expect(Tok::RBracket, "']'")?;
                    Ok((None, Some(IndexSpec::Index(start.unwrap_or(0)))))
                }
            }
            _ => Err(QueryError::spanned(
                "Invalid filter: expected filter pattern or index".to_string(),
                t.start,
                t.end,
                "invalid filter",
            )),
        }
    }

    fn parse_opt_int(&mut self) -> Result<Option<i64>, QueryError> {
        let mut neg = false;
        if *self.peek_tok() == Tok::Minus {
            self.advance();
            neg = true;
        }
        match self.peek_tok().clone() {
            Tok::Number(n) => {
                self.advance();
                let v = n as i64;
                Ok(Some(if neg { -v } else { v }))
            }
            _ => {
                if neg {
                    Err(self.unexpected("number"))
                } else {
                    Ok(None)
                }
            }
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, QueryError> {
        let t = self.peek().clone();
        match &t.tok {
            Tok::Dot => {
                self.advance();
                match self.peek_tok().clone() {
                    Tok::Ident(name) => {
                        self.advance();
                        if let Some(kind) = SelKind::from_name(&name) {
                            Ok(Expr::Selector { kind, filter: None, index: None })
                        } else {
                            Ok(Expr::Field(name))
                        }
                    }
                    Tok::Eof | Tok::Pipe | Tok::RParen | Tok::RBracket | Tok::RBrace | Tok::Comma
                    | Tok::KwThen | Tok::KwElse | Tok::KwEnd | Tok::KwAnd | Tok::KwOr => Ok(Expr::Identity),
                    _ => Err(self.unexpected("identifier")),
                }
            }
            Tok::Number(n) => {
                let n = *n;
                self.advance();
                Ok(Expr::Literal(Value::Number(n)))
            }
            Tok::Str(s) => {
                let s = s.clone();
                self.advance();
                Ok(Expr::Literal(Value::String(s)))
            }
            Tok::LBracket => {
                self.advance();
                let mut items = Vec::new();
                if *self.peek_tok() != Tok::RBracket {
                    loop {
                        items.push(self.parse_pipe()?);
                        if *self.peek_tok() == Tok::Comma {
                            self.advance();
                            continue;
                        }
                        break;
                    }
                }
                self.expect(Tok::RBracket, "']'")?;
                Ok(Expr::Array(items))
            }
            Tok::LBrace => {
                self.advance();
                let mut entries = Vec::new();
                if *self.peek_tok() != Tok::RBrace {
                    loop {
                        let key = match self.peek_tok().clone() {
                            Tok::Ident(k) => {
                                self.advance();
                                k
                            }
                            Tok::Str(k) => {
                                self.advance();
                                k
                            }
                            _ => return Err(self.unexpected("one of identifier, string")),
                        };
                        self.expect(Tok::Colon, "':'")?;
                        let v = self.parse_pipe()?;
                        entries.push((key, v));
                        if *self.peek_tok() == Tok::Comma {
                            self.advance();
                            continue;
                        }
                        break;
                    }
                }
                self.expect(Tok::RBrace, "'}'")?;
                Ok(Expr::Object(entries))
            }
            Tok::LParen => {
                self.advance();
                let e = self.parse_pipe()?;
                self.expect(Tok::RParen, "')'")?;
                Ok(e)
            }
            Tok::KwIf => {
                self.advance();
                let cond = self.parse_pipe()?;
                if *self.peek_tok() != Tok::KwThen {
                    let t = self.peek();
                    return Err(QueryError::spanned(
                        "Expected 'then' after condition".to_string(),
                        t.start,
                        t.end,
                        "expected 'then'",
                    ));
                }
                self.advance();
                let then = self.parse_pipe()?;
                let otherwise = if *self.peek_tok() == Tok::KwElse {
                    self.advance();
                    Some(Box::new(self.parse_pipe()?))
                } else {
                    None
                };
                if *self.peek_tok() != Tok::KwEnd {
                    let t = self.peek();
                    return Err(QueryError::spanned(
                        "Expected 'end' to close conditional".to_string(),
                        t.start,
                        t.end,
                        "expected 'end'",
                    ));
                }
                self.advance();
                Ok(Expr::If { cond: Box::new(cond), then: Box::new(then), otherwise })
            }
            Tok::Ident(name) => {
                let name = name.clone();
                let start = t.start;
                let mut end = t.end;
                self.advance();
                let mut args = Vec::new();
                match name.as_str() {
                    "true" => return Ok(Expr::Literal(Value::Bool(true))),
                    "false" => return Ok(Expr::Literal(Value::Bool(false))),
                    "null" => return Ok(Expr::Literal(Value::Null)),
                    _ => {}
                }
                if *self.peek_tok() == Tok::LParen {
                    self.advance();
                    if *self.peek_tok() != Tok::RParen {
                        loop {
                            args.push(self.parse_pipe()?);
                            if *self.peek_tok() == Tok::Comma {
                                self.advance();
                                continue;
                            }
                            break;
                        }
                    }
                    let close = self.expect(Tok::RParen, "')'")?;
                    end = close.end;
                }
                Ok(Expr::Call { name, args, span: (start, end) })
            }
            _ => Err(self.unexpected("expression")),
        }
    }
}

pub fn parse(src: &str) -> Result<Expr, QueryError> {
    let toks = super::lexer::tokenize(src)?;
    Parser::new(toks).parse_query()
}
