//! Query AST.

use super::value::Value;

#[derive(Debug, Clone, PartialEq)]
pub enum SelKind {
    Heading(Option<u8>),
    Code,
    Link,
    Image,
    Table,
    List,
    BlockQuote,
    Paragraph,
}

impl SelKind {
    pub fn from_name(name: &str) -> Option<SelKind> {
        match name {
            "h" | "heading" | "headings" | "header" | "headers" => Some(SelKind::Heading(None)),
            "h1" => Some(SelKind::Heading(Some(1))),
            "h2" => Some(SelKind::Heading(Some(2))),
            "h3" => Some(SelKind::Heading(Some(3))),
            "h4" => Some(SelKind::Heading(Some(4))),
            "h5" => Some(SelKind::Heading(Some(5))),
            "h6" => Some(SelKind::Heading(Some(6))),
            "code" | "codeblock" | "codeblocks" => Some(SelKind::Code),
            "link" | "links" | "a" | "anchor" => Some(SelKind::Link),
            "img" | "image" | "images" => Some(SelKind::Image),
            "table" | "tables" => Some(SelKind::Table),
            "list" | "lists" => Some(SelKind::List),
            "quote" | "quotes" | "blockquote" | "blockquotes" => Some(SelKind::BlockQuote),
            "paragraph" | "paragraphs" | "p" => Some(SelKind::Paragraph),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct TextFilter {
    pub pattern: String,
    pub exact: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum IndexSpec {
    Index(i64),
    Slice(Option<i64>, Option<i64>),
}

#[derive(Debug, Clone, PartialEq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Identity,
    Selector { kind: SelKind, filter: Option<TextFilter>, index: Option<IndexSpec> },
    Field(String),
    Literal(Value),
    Array(Vec<Expr>),
    Object(Vec<(String, Expr)>),
    Pipe(Box<Expr>, Box<Expr>),
    Call { name: String, args: Vec<Expr>, span: (usize, usize) },
    Binary { op: BinOp, lhs: Box<Expr>, rhs: Box<Expr> },
    Not(Box<Expr>),
    Neg(Box<Expr>),
    If { cond: Box<Expr>, then: Box<Expr>, otherwise: Option<Box<Expr>> },
    Child { parent: Box<Expr>, child: Box<Expr>, direct: bool },
}
