//! Recursive descent parser for the query language.

use super::ast::*;
use super::error::QueryError;
use super::lexer::{Tok, Token};
use super::value::Value;

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(toks: Vec<Token>) -> Self {
        Parser { toks, pos: 0 }
    }

    fn peek(&self) -> &Token {
        &self.toks[self.pos.min(self.toks.len() - 1)]
    }

    fn peek_tok(&self) -> &Tok {
        &self.peek().tok
    }

    fn peek_at(&self, n: usize) -> &Tok {
        &self.toks[(self.pos + n).min(self.toks.len() - 1)].tok
    }

    fn advance(&mut self) -> Token {
        let t = self.peek().clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn unexpected(&self, expected: &str) -> QueryError {
        let t = self.peek();
        QueryError::spanned(
            format!("Expected {}, found {}", expected, t.tok.describe()),
            t.start,
            t.end,
            "unexpected token",
        )
    }

    fn expect(&mut self, tok: Tok, desc: &str) -> Result<Token, QueryError> {
        if *self.peek_tok() == tok {
            Ok(self.advance())
        } else {
            Err(self.unexpected(desc))
        }
    }

    pub fn parse_query(&mut self) -> Result<Expr, QueryError> {
        let e = self.parse_pipe()?;
        if *self.peek_tok() != Tok::Eof {
            return Err(self.unexpected("end of query"));
        }
        Ok(e)
    }

    fn parse_pipe(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_or()?;
        while *self.peek_tok() == Tok::Pipe {
            self.advance();
            let rhs = self.parse_or()?;
            lhs = Expr::Pipe(Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_or(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_and()?;
        while *self.peek_tok() == Tok::KwOr {
            self.advance();
            let rhs = self.parse_and()?;
            lhs = Expr::Binary { op: BinOp::Or, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_and(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_comparison()?;
        while *self.peek_tok() == Tok::KwAnd {
            self.advance();
            let rhs = self.parse_comparison()?;
            lhs = Expr::Binary { op: BinOp::And, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_comparison(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_additive()?;
        loop {
            let op = match self.peek_tok() {
                Tok::EqEq => BinOp::Eq,
                Tok::NotEq => BinOp::Ne,
                Tok::Lt => BinOp::Lt,
                Tok::Le => BinOp::Le,
                Tok::Ge => BinOp::Ge,
                Tok::Gt | Tok::GtGt => {
                    let direct = *self.peek_tok() == Tok::Gt;
                    if *self.peek_at(1) == Tok::Dot || !direct {
                        self.advance();
                        let child = self.parse_additive()?;
                        lhs = Expr::Child { parent: Box::new(lhs), child: Box::new(child), direct };
                        continue;
                    }
                    BinOp::Gt
                }
                _ => break,
            };
            self.advance();
            let rhs = self.parse_additive()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_additive(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_multiplicative()?;
        loop {
            let op = match self.peek_tok() {
                Tok::Plus => BinOp::Add,
                Tok::Minus => BinOp::Sub,
                _ => break,
            };
            self.advance();
            let rhs = self.parse_multiplicative()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, QueryError> {
        let mut lhs = self.parse_unary()?;
        loop {
            let op = match self.peek_tok() {
                Tok::Star => BinOp::Mul,
                Tok::Slash => BinOp::Div,
                Tok::Percent => BinOp::Mod,
                _ => break,
            };
            self.advance();
            let rhs = self.parse_unary()?;
            lhs = Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        Ok(lhs)
    }

    fn parse_unary(&mut self) -> Result<Expr, QueryError> {
        match self.peek_tok() {
            Tok::KwNot => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Not(Box::new(e)))
            }
            Tok::Minus => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Neg(Box::new(e)))
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Result<Expr, QueryError> {
        let mut e = self.parse_primary()?;
        loop {
            match self.peek_tok() {
                Tok::LBracket => {
                    self.advance();
                    let (filter, index) = self.parse_filter()?;
                    if let Expr::Selector { filter: f, index: i, .. } = &mut e {
