    pub children: Vec<Vec<usize>>,
    pub source: String,
}

fn collect_links(nodes: &[Inline], src: &str, out: &mut Vec<LinkValue>) {
    for n in nodes {
        if let Inline::Link { text, url, .. } = n {
            let needle = format!("[{}]({})", text, url);
            let offset = src.find(&needle).unwrap_or(0);
            out.push(LinkValue { text: text.clone(), url: url.clone(), link_type: LinkType::classify(url), offset });
        }
    }
}

fn walk_blocks(blocks: &[Block], src: &str, els: &mut Elements) {
    for b in blocks {
        match b {
            Block::Heading { inline, .. } => collect_links(inline, src, &mut els.links),
            Block::Paragraph { inline } => collect_links(inline, src, &mut els.links),
            Block::Code { language, content } => els.codes.push(CodeValue {
                language: language.clone(),
                content: content.clone(),
                start_line: 1,
                end_line: 1,
            }),
            Block::List { ordered, items, .. } => {
                for it in items {
                    collect_links(&it.inline, src, &mut els.links);
                    walk_blocks(&it.blocks, src, els);
                }
                els.lists.push(ListValue {
                    ordered: *ordered,
                    items: items
                        .iter()
                        .map(|i| ListItemValue { content: i.content.clone(), checked: i.checked })
                        .collect(),
                });
            }
            Block::Table { headers, alignments, rows, header_inline, row_inline } => {
                for h in header_inline {
                    collect_links(h, src, &mut els.links);
                }
                for r in row_inline {
                    for c in r {
                        collect_links(c, src, &mut els.links);
                    }
                }
                els.tables.push(TableValue { headers: headers.clone(), rows: rows.clone(), alignments: alignments.clone() });
            }
            Block::BlockQuote { links, .. } => collect_links(links, src, &mut els.links),
            Block::HorizontalRule | Block::Html { .. } => {}
        }
    }
}

impl Elements {
    pub fn from_document(doc: &Document) -> Elements {
        let mut els = Elements {
            document: DocumentValue {
                content: doc.source.clone(),
                heading_count: doc.headings.len(),
                word_count: doc.word_count(),
            },
            headings: Vec::new(),
            codes: Vec::new(),
            links: Vec::new(),
            tables: Vec::new(),
            lists: Vec::new(),
            children: vec![Vec::new(); doc.headings.len()],
            source: doc.source.clone(),
        };
        for (i, h) in doc.headings.iter().enumerate() {
            els.headings.push(HeadingValue {
                level: h.level,
                text: h.text.clone(),
                offset: h.offset,
                line: h.line,
                content: doc.section_content(i).to_string(),
                raw_md: doc.section_raw_md(i).to_string(),
                index: i,
            });
        }
        let tree = build_tree(&doc.headings);
        fn fill(nodes: &[HeadingNode], children: &mut Vec<Vec<usize>>) {
            for n in nodes {
                children[n.idx] = n.children.iter().map(|c| c.idx).collect();
                fill(&n.children, children);
            }
        }
        fill(&tree, &mut els.children);

        let blocks = parse_blocks(&doc.source, &doc.refs);
        walk_blocks(&blocks, &doc.source, &mut els);
        els
    }

