//! Query evaluation.

use indexmap::IndexMap;

use super::ast::*;
use super::elements::Elements;
use super::error::QueryError;
use super::value::*;
use crate::md::document::slugify;

pub const FUNCTION_NAMES: &[&str] = &[
    "count", "length", "first", "last", "limit", "skip", "nth", "reverse", "sort", "sort_by", "unique",
    "flatten", "group_by", "min", "max", "add", "text", "upper", "lower", "trim", "split", "join",
    "replace", "slugify", "lines", "words", "chars", "select", "contains", "startswith", "endswith",
    "matches", "any", "all", "not", "has", "type", "keys", "values", "empty", "content", "md", "url",
    "lang", "stats", "levels", "langs", "types", "debug",
];

pub struct Evaluator<'a> {
    pub els: &'a Elements,
    pub debug_out: Vec<String>,
}

type R = Result<Vec<Value>, QueryError>;

fn resolve_index(i: i64, len: usize) -> Option<usize> {
    let idx = if i < 0 { len as i64 + i } else { i };
    if idx < 0 || idx >= len as i64 {
        None
    } else {
        Some(idx as usize)
    }
}

fn resolve_slice(start: Option<i64>, end: Option<i64>, len: usize) -> (usize, usize) {
    let norm = |v: i64| -> usize {
        let x = if v < 0 { len as i64 + v } else { v };
        x.clamp(0, len as i64) as usize
    };
    let s = start.map(norm).unwrap_or(0);
    let e = end.map(norm).unwrap_or(len);
    (s, e.max(s))
}

fn apply_index(items: Vec<Value>, index: &Option<IndexSpec>) -> Vec<Value> {
    match index {
        None => items,
        Some(IndexSpec::Index(i)) => match resolve_index(*i, items.len()) {
            Some(idx) => vec![items[idx].clone()],
            None => vec![],
        },
        Some(IndexSpec::Slice(s, e)) => {
            let (a, b) = resolve_slice(*s, *e, items.len());
            items[a..b].to_vec()
        }
    }
}

fn matches_filter(v: &Value, f: &TextFilter) -> bool {
    let pat = f.pattern.to_lowercase();
    if f.exact {
        return v.to_text().to_lowercase() == pat;
    }
    match v {
        Value::Link(l) => l.text.to_lowercase().contains(&pat) || l.link_type.as_str() == f.pattern,
        Value::Table(t) => {
            t.headers.iter().any(|h| h.to_lowercase().contains(&pat))
                || t.rows.iter().any(|r| r.iter().any(|c| c.to_lowercase().contains(&pat)))
        }
        other => other.to_text().to_lowercase().contains(&pat),
    }
}

impl<'a> Evaluator<'a> {
    pub fn new(els: &'a Elements) -> Self {
        Evaluator { els, debug_out: Vec::new() }
    }

    fn select_all(&self, kind: &SelKind) -> Vec<Value> {
        match kind {
            SelKind::Heading(level) => self
                .els
                .headings
                .iter()
                .filter(|h| level.map(|l| h.level == l).unwrap_or(true))
                .map(|h| Value::Heading(h.clone()))
                .collect(),
            SelKind::Code => self.els.codes.iter().map(|c| Value::Code(c.clone())).collect(),
            SelKind::Link => self.els.links.iter().map(|l| Value::Link(l.clone())).collect(),
            SelKind::Table => self.els.tables.iter().map(|t| Value::Table(t.clone())).collect(),
            SelKind::List => self.els.lists.iter().map(|l| Value::List(l.clone())).collect(),
            SelKind::Image | SelKind::BlockQuote | SelKind::Paragraph => vec![],
        }
    }

    fn apply_selector_filters(&self, items: Vec<Value>, filter: &Option<TextFilter>, index: &Option<IndexSpec>) -> Vec<Value> {
        let items: Vec<Value> = match filter {
            Some(f) => items.into_iter().filter(|v| matches_filter(v, f)).collect(),
            None => items,
        };
        apply_index(items, index)
    }

    pub fn eval(&mut self, expr: &Expr, ctx: &Value) -> R {
        match expr {
            Expr::Identity => Ok(vec![ctx.clone()]),
            Expr::Literal(v) => Ok(vec![v.clone()]),
            Expr::Selector { kind, filter, index } => {
                let items = self.select_all(kind);
                Ok(self.apply_selector_filters(items, filter, index))
            }
            Expr::Field(name) => self.field(ctx, name).map(|v| vec![v]),
            Expr::Array(items) => {
                let mut out = Vec::new();
                for it in items {
                    out.extend(self.eval(it, ctx)?);
                }
                Ok(vec![Value::Array(out)])
            }
            Expr::Object(entries) => {
                let mut m = IndexMap::new();
                for (k, e) in entries {
                    let vals = self.eval(e, ctx)?;
                    m.insert(k.clone(), vals.into_iter().next().unwrap_or(Value::Null));
                }
                Ok(vec![Value::Object(m)])
            }
            Expr::Pipe(a, b) => {
                let mut out = Vec::new();
                for v in self.eval(a, ctx)? {
                    out.extend(self.eval(b, &v)?);
                }
                Ok(out)
            }
            Expr::Call { name, args, .. } => self.call(name, args, ctx),
            Expr::Binary { op, lhs, rhs } => {
                let l = self.eval(lhs, ctx)?;
                let r = self.eval(rhs, ctx)?;
                let mut out = Vec::new();
                for a in &l {
                    for b in &r {
                        out.push(binary(op, a, b)?);
                    }
                }
                Ok(out)
            }
            Expr::Not(e) => {
                let v = self.eval(e, ctx)?;
                let t = v.first().map(|x| x.truthy()).unwrap_or(false);
                Ok(vec![Value::Bool(!t)])
            }
            Expr::Neg(e) => {
                let v = self.eval(e, ctx)?;
                Ok(v
                    .into_iter()
                    .map(|x| match x {
                        Value::Number(n) => Value::Number(-n),
                        _ => Value::Null,
                    })
                    .collect())
            }
            Expr::If { cond, then, otherwise } => {
                let c = self.eval(cond, ctx)?;
                let t = c.first().map(|x| x.truthy()).unwrap_or(false);
                if t {
                    self.eval(then, ctx)
                } else if let Some(o) = otherwise {
                    self.eval(o, ctx)
                } else {
                    Ok(vec![Value::Null])
                }
            }
            Expr::Child { parent, child, direct } => {
                let parents = self.eval(parent, ctx)?;
                let mut out = Vec::new();
                for p in parents {
                    if let Value::Heading(h) = &p {
                        if let Expr::Selector { kind, filter, index } = &**child {
                            match kind {
                                SelKind::Heading(level) => {
                                    let mut idxs = Vec::new();
                                    if *direct {
                                        idxs.extend(self.els.children[h.index].iter().cloned());
                                    } else {
                                        self.els.descendants(h.index, &mut idxs);
                                    }
                                    let items: Vec<Value> = idxs
                                        .into_iter()
                                        .map(|i| &self.els.headings[i])
                                        .filter(|c| level.map(|l| c.level == l).unwrap_or(true))
                                        .map(|c| Value::Heading(c.clone()))
                                        .collect();
                                    out.extend(self.apply_selector_filters(items, filter, index));
                                }
                                SelKind::Code => {
                                    let items = self.select_all(kind);
                                    out.extend(self.apply_selector_filters(items, filter, index));
                                }
                                _ => {}
                            }
                        }
                    }
                }
                Ok(out)
            }
        }
    }

    fn field(&self, ctx: &Value, name: &str) -> Result<Value, QueryError> {
        let missing = || QueryError::new(format!("Property '{}' not found on {}", name, ctx.type_name()));
        match ctx {
            Value::Document(d) => match name {
                "content" | "text" => Ok(Value::String(d.content.clone())),
                "heading_count" => Ok(Value::Number(d.heading_count as f64)),
                "word_count" => Ok(Value::Number(d.word_count as f64)),
                _ => Err(missing()),
            },
            Value::Heading(h) => match name {
                "level" => Ok(Value::Number(h.level as f64)),
                "text" => Ok(Value::String(h.text.clone())),
                "line" => Ok(Value::Number(h.line as f64)),
                "offset" => Ok(Value::Number(h.offset as f64)),
                "content" => Ok(Value::String(h.content.clone())),
                "md" => Ok(Value::String(h.raw_md.clone())),
                "slug" => Ok(Value::String(slugify(&h.text))),
                _ => Err(missing()),
            },
            Value::Code(c) => match name {
                "language" | "lang" => Ok(c.language.clone().map(Value::String).unwrap_or(Value::Null)),
                "content" | "text" => Ok(Value::String(c.content.clone())),
                "start_line" => Ok(Value::Number(c.start_line as f64)),
                "end_line" => Ok(Value::Number(c.end_line as f64)),
                _ => Err(missing()),
            },
            Value::Link(l) => match name {
                "text" => Ok(Value::String(l.text.clone())),
                "url" => Ok(Value::String(l.url.clone())),
                "type" => Ok(Value::String(l.link_type.as_str().to_string())),
                "offset" => Ok(Value::Number(l.offset as f64)),
                _ => Err(missing()),
            },
            Value::Table(t) => match name {
                "headers" => Ok(Value::Array(t.headers.iter().map(|h| Value::String(h.clone())).collect())),
                "rows" => Ok(Value::Array(
                    t.rows
                        .iter()
                        .map(|r| Value::Array(r.iter().map(|c| Value::String(c.clone())).collect()))
                        .collect(),
                )),
                "alignments" => Ok(Value::Array(t.alignments.iter().map(|a| Value::String(a.clone())).collect())),
                _ => Err(missing()),
            },
            Value::List(l) => match name {
                "ordered" => Ok(Value::Bool(l.ordered)),
                "items" => Ok(Value::Array(l.items.iter().map(|i| Value::String(i.content.clone())).collect())),
                _ => Err(missing()),
            },
            Value::Object(o) => o.get(name).cloned().ok_or_else(missing),
            _ => Err(missing()),
        }
    }

    fn arity(&self, name: &str, args: &[Expr], min: usize, max: usize) -> Result<(), QueryError> {
        if args.len() < min || args.len() > max {
            return Err(QueryError::new(format!(
                "Function '{}' expects {}..={} arguments, got {}",
                name, min, max, args.len()
            )));
        }
        Ok(())
    }

    fn arg(&mut self, args: &[Expr], i: usize, ctx: &Value) -> Result<Value, QueryError> {
        let vals = self.eval(&args[i], ctx)?;
        Ok(vals.into_iter().next().unwrap_or(Value::Null))
    }

    fn call(&mut self, name: &str, args: &[Expr], ctx: &Value) -> R {
        let one = |v: Value| -> R { Ok(vec![v]) };
        match name {
            // ---- collection functions ----
            "count" | "length" | "len" | "size" => {
                self.arity(name, args, 0, 0)?;
                let n = match ctx {
                    Value::Array(a) => a.len(),
                    Value::Object(o) => o.len(),
                    Value::String(s) => s.len(),
                    _ => 1,
                };
                one(Value::Number(n as f64))
            }
            "first" | "head" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => one(a.first().cloned().unwrap_or(Value::Null)),
                    Value::String(s) => one(s.chars().next().map(|c| Value::String(c.to_string())).unwrap_or(Value::Null)),
                    other => one(other.clone()),
                }
            }
            "last" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => one(a.last().cloned().unwrap_or(Value::Null)),
                    Value::String(s) => one(s.chars().last().map(|c| Value::String(c.to_string())).unwrap_or(Value::Null)),
                    other => one(other.clone()),
                }
            }
            "limit" | "take" => {
                self.arity(name, args, 1, 1)?;
                let n = self.arg(args, 0, ctx)?.as_number().unwrap_or(0.0).max(0.0) as usize;
                match ctx {
                    Value::Array(a) => one(Value::Array(a.iter().take(n).cloned().collect())),
                    Value::String(s) => one(Value::String(s.chars().take(n).collect())),
                    other => one(other.clone()),
                }
            }
            "skip" | "drop" => {
                self.arity(name, args, 1, 1)?;
                let n = self.arg(args, 0, ctx)?.as_number().unwrap_or(0.0).max(0.0) as usize;
                match ctx {
                    Value::Array(a) => one(Value::Array(a.iter().skip(n).cloned().collect())),
                    Value::String(s) => one(Value::String(s.chars().skip(n).collect())),
                    other => one(other.clone()),
                }
            }
            "nth" => {
                self.arity(name, args, 1, 1)?;
                let n = match self.arg(args, 0, ctx)? {
                    Value::Number(n) => n as i64,
                    _ => return one(Value::Null),
                };
                match ctx {
                    Value::Array(a) => one(resolve_index(n, a.len()).map(|i| a[i].clone()).unwrap_or(Value::Null)),
                    Value::String(s) => {
                        let chars: Vec<char> = s.chars().collect();
                        one(resolve_index(n, chars.len()).map(|i| Value::String(chars[i].to_string())).unwrap_or(Value::Null))
                    }
                    _ => one(Value::Null),
                }
            }
            "reverse" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => one(Value::Array(a.iter().rev().cloned().collect())),
                    Value::String(s) => one(Value::String(s.chars().rev().collect())),
                    other => one(other.clone()),
                }
            }
            "sort" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => {
                        let mut v = a.clone();
                        v.sort_by(|x, y| compare_values(x, y));
                        one(Value::Array(v))
                    }
                    other => one(other.clone()),
                }
            }
            "sort_by" => {
                self.arity(name, args, 1, 1)?;
                let key = self.arg(args, 0, ctx)?.to_text();
                match ctx {
                    Value::Array(a) => {
                        let mut v = a.clone();
                        v.sort_by(|x, y| {
                            let kx = sort_key(x, &key);
                            let ky = sort_key(y, &key);
                            match (&kx, &ky) {
                                (Value::Number(p), Value::Number(q)) => p.partial_cmp(q).unwrap_or(std::cmp::Ordering::Equal),
                                _ => kx.to_text().cmp(&ky.to_text()),
                            }
                        });
                        one(Value::Array(v))
                    }
                    other => one(other.clone()),
                }
            }
            "unique" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => {
                        let mut out: Vec<Value> = Vec::new();
                        for v in a {
                            if !out.iter().any(|o| o == v) {
                                out.push(v.clone());
                            }
                        }
                        one(Value::Array(out))
                    }
                    other => one(other.clone()),
                }
            }
            "flatten" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => {
                        let mut out = Vec::new();
                        flatten_into(a, &mut out);
                        one(Value::Array(out))
                    }
                    other => one(other.clone()),
                }
            }
            "group_by" => {
                self.arity(name, args, 1, 1)?;
                let key = self.arg(args, 0, ctx)?.to_text();
                match ctx {
                    Value::Array(a) => {
                        let mut groups: IndexMap<String, Vec<Value>> = IndexMap::new();
                        for v in a {
                            let k = group_key(v, &key);
                            groups.entry(k).or_default().push(v.clone());
                        }
                        let mut m = IndexMap::new();
                        for (k, vs) in groups {
                            m.insert(k, Value::Array(vs));
                        }
                        one(Value::Object(m))
                    }
                    other => one(other.clone()),
                }
            }
            "min" | "max" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => {
                        let nums: Vec<f64> = a.iter().filter_map(|v| v.as_number()).collect();
                        if nums.is_empty() {
                            return one(Value::Null);
                        }
                        let r = if name == "min" {
                            nums.iter().cloned().fold(f64::INFINITY, f64::min)
                        } else {
                            nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max)
                        };
                        one(Value::Number(r))
                    }
                    other => one(other.clone()),
                }
            }
            "add" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Array(a) => {
                        if a.is_empty() {
                            return one(Value::Number(0.0));
                        }
                        if a.iter().all(|v| matches!(v, Value::Number(_))) {
                            let s: f64 = a.iter().filter_map(|v| v.as_number()).sum();
                            return one(Value::Number(s));
                        }
                        let s: String = a.iter().map(|v| v.to_text()).collect();
                        one(Value::String(s))
                    }
                    other => one(other.clone()),
                }
            }
            // ---- string functions ----
            "text" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(ctx.to_text()))
            }
            "upper" | "ascii_upcase" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(ctx.to_text().to_uppercase()))
            }
            "lower" | "ascii_downcase" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(ctx.to_text().to_lowercase()))
            }
            "trim" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(ctx.to_text().trim().to_string()))
            }
            "split" => {
                self.arity(name, args, 1, 1)?;
                let sep = self.arg(args, 0, ctx)?.to_text();
                let s = ctx.to_text();
                let parts: Vec<Value> = if sep.is_empty() {
                    s.split("").map(|p| Value::String(p.to_string())).collect()
                } else {
                    s.split(sep.as_str()).map(|p| Value::String(p.to_string())).collect()
                };
                one(Value::Array(parts))
            }
            "join" => {
                self.arity(name, args, 1, 1)?;
                let sep = self.arg(args, 0, ctx)?.to_text();
                match ctx {
                    Value::Array(a) => one(Value::String(a.iter().map(|v| v.to_text()).collect::<Vec<_>>().join(&sep))),
                    other => one(Value::String(other.to_text())),
                }
            }
            "replace" => {
                self.arity(name, args, 2, 2)?;
                let from = self.arg(args, 0, ctx)?.to_text();
                let to = self.arg(args, 1, ctx)?.to_text();
                one(Value::String(ctx.to_text().replace(&from, &to)))
            }
            "slugify" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(slugify(&ctx.to_text())))
            }
            "lines" => {
                self.arity(name, args, 0, 0)?;
                one(Value::Number(ctx.to_text().lines().count() as f64))
            }
            "words" => {
                self.arity(name, args, 0, 0)?;
                one(Value::Number(ctx.to_text().split_whitespace().count() as f64))
            }
            "chars" => {
                self.arity(name, args, 0, 0)?;
                one(Value::Number(ctx.to_text().chars().count() as f64))
            }
            // ---- filter functions ----
            "select" | "where" | "filter" => {
                self.arity(name, args, 1, 1)?;
                let c = self.eval(&args[0], ctx)?;
                if c.first().map(|v| v.truthy()).unwrap_or(false) {
                    one(ctx.clone())
                } else {
                    Ok(vec![])
                }
            }
            "contains" | "includes" => {
                self.arity(name, args, 1, 1)?;
                let needle = self.arg(args, 0, ctx)?.to_text().to_lowercase();
                one(Value::Bool(ctx.to_text().to_lowercase().contains(&needle)))
            }
            "startswith" => {
                self.arity(name, args, 1, 1)?;
                let needle = self.arg(args, 0, ctx)?.to_text().to_lowercase();
                one(Value::Bool(ctx.to_text().to_lowercase().starts_with(&needle)))
            }
            "endswith" => {
                self.arity(name, args, 1, 1)?;
                let needle = self.arg(args, 0, ctx)?.to_text().to_lowercase();
                one(Value::Bool(ctx.to_text().to_lowercase().ends_with(&needle)))
            }
            "matches" => {
                self.arity(name, args, 1, 1)?;
                let pat = match self.arg(args, 0, ctx)? {
                    Value::String(s) => s,
                    _ => return one(Value::Bool(false)),
                };
                let re = regex::Regex::new(&pat);
                match re {
                    Ok(re) => one(Value::Bool(re.is_match(&ctx.to_text()))),
                    Err(_) => one(Value::Bool(false)),
                }
            }
            "any" | "all" => {
                self.arity(name, args, 1, 1)?;
                match ctx {
                    Value::Array(a) => {
                        let mut results = Vec::new();
                        for v in a {
                            let c = self.eval(&args[0], v)?;
                            results.push(c.first().map(|x| x.truthy()).unwrap_or(false));
                        }
                        let r = if name == "any" { results.iter().any(|b| *b) } else { results.iter().all(|b| *b) };
                        one(Value::Bool(r))
                    }
                    other => {
                        let c = self.eval(&args[0], other)?;
                        one(Value::Bool(c.first().map(|x| x.truthy()).unwrap_or(false)))
                    }
                }
            }
            "has" => {
                self.arity(name, args, 1, 1)?;
                let key = self.arg(args, 0, ctx)?;
                match (ctx, &key) {
                    (Value::Object(o), Value::String(k)) => one(Value::Bool(o.contains_key(k))),
                    _ => one(Value::Bool(false)),
                }
            }
            "type" => {
                self.arity(name, args, 0, 0)?;
                one(Value::String(ctx.type_name().to_string()))
            }
            "keys" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Object(o) => one(Value::Array(o.keys().map(|k| Value::String(k.clone())).collect())),
                    Value::Array(a) => one(Value::Array((0..a.len()).map(|i| Value::Number(i as f64)).collect())),
                    _ => one(Value::Array(vec![])),
                }
            }
            "values" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Object(o) => one(Value::Array(o.values().cloned().collect())),
                    Value::Array(a) => one(Value::Array(a.clone())),
                    _ => one(Value::Array(vec![])),
                }
            }
            "empty" => {
                self.arity(name, args, 0, 0)?;
                let e = match ctx {
                    Value::Array(a) => a.is_empty(),
                    Value::Object(o) => o.is_empty(),
                    Value::String(s) => s.is_empty(),
                    Value::Null => true,
                    _ => false,
                };
                one(Value::Bool(e))
            }
            // ---- content functions ----
            "content" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Heading(h) => one(Value::String(h.content.clone())),
                    other => one(Value::String(other.to_text())),
                }
            }
            "md" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Heading(h) => one(Value::String(h.raw_md.clone())),
                    other => one(Value::String(other.to_text())),
                }
            }
            "url" | "href" | "src" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Link(l) => one(Value::String(l.url.clone())),
                    _ => one(Value::Null),
                }
            }
            "lang" | "language" => {
                self.arity(name, args, 0, 0)?;
                match ctx {
                    Value::Code(c) => one(c.language.clone().map(Value::String).unwrap_or(Value::Null)),
                    _ => one(Value::Null),
                }
            }
            // ---- aggregation ----
            "stats" => {
                self.arity(name, args, 0, 0)?;
                let mut m = IndexMap::new();
                m.insert("headings".to_string(), Value::Number(self.els.headings.len() as f64));
                m.insert("code_blocks".to_string(), Value::Number(self.els.codes.len() as f64));
                m.insert("links".to_string(), Value::Number(self.els.links.len() as f64));
                m.insert("images".to_string(), Value::Number(0.0));
                m.insert("tables".to_string(), Value::Number(self.els.tables.len() as f64));
                m.insert("lists".to_string(), Value::Number(self.els.lists.len() as f64));
                m.insert("words".to_string(), Value::Number(self.els.document.word_count as f64));
                one(Value::Object(m))
            }
            "levels" => {
                self.arity(name, args, 0, 0)?;
                let mut counts = [0usize; 7];
                for h in &self.els.headings {
                    if (1..=6).contains(&(h.level as usize)) {
                        counts[h.level as usize] += 1;
                    }
                }
                let mut m = IndexMap::new();
                for l in 1..=6 {
                    if counts[l] > 0 {
                        m.insert(format!("h{}", l), Value::Number(counts[l] as f64));
                    }
                }
                one(Value::Object(m))
            }
            "langs" => {
                self.arity(name, args, 0, 0)?;
                let mut m: IndexMap<String, f64> = IndexMap::new();
                for c in &self.els.codes {
                    let k = c.language.clone().unwrap_or_else(|| "none".to_string());
                    *m.entry(k).or_insert(0.0) += 1.0;
                }
                one(Value::Object(m.into_iter().map(|(k, v)| (k, Value::Number(v))).collect()))
            }
            "types" => {
                self.arity(name, args, 0, 0)?;
                let mut m: IndexMap<String, f64> = IndexMap::new();
                for l in &self.els.links {
                    *m.entry(l.link_type.as_str().to_string()).or_insert(0.0) += 1.0;
                }
                one(Value::Object(m.into_iter().map(|(k, v)| (k, Value::Number(v))).collect()))
            }
            "debug" => {
                self.arity(name, args, 0, 0)?;
                self.debug_out.push(format!("[DEBUG] {}", ctx.debug_repr()));
                one(ctx.clone())
            }
            _ => Err(QueryError::new(format!("Unknown function '{}'", name)).with_suggestions(suggest(name))),
        }
    }
}

fn flatten_into(a: &[Value], out: &mut Vec<Value>) {
    for v in a {
        match v {
            Value::Array(inner) => flatten_into(inner, out),
            other => out.push(other.clone()),
        }
    }
}

pub fn compare_values(x: &Value, y: &Value) -> std::cmp::Ordering {
    match (x, y) {
        (Value::Number(a), Value::Number(b)) => a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal),
        _ => x.to_text().cmp(&y.to_text()),
    }
}

fn sort_key(v: &Value, key: &str) -> Value {
    match v {
        Value::Heading(h) => {
            if key == "level" {
                Value::Number(h.level as f64)
            } else {
                Value::String(h.text.clone())
            }
        }
        Value::Object(o) => o.get(key).cloned().unwrap_or(Value::Null),
        Value::Number(n) => Value::Number(*n),
        other => Value::String(other.to_text()),
    }
}

fn group_key(v: &Value, key: &str) -> String {
    match v {
        Value::Heading(h) => format!("h{}", h.level),
        Value::Code(c) => c.language.clone().unwrap_or_else(|| "none".to_string()),
        Value::Object(o) => o.get(key).map(|x| x.to_text()).unwrap_or_default(),
        other => other.to_text(),
    }
}

pub fn suggest(name: &str) -> Vec<String> {
    let mut scored: Vec<(usize, &str)> = FUNCTION_NAMES
        .iter()
        .map(|f| (strsim::levenshtein(name, f), *f))
        .filter(|(d, _)| *d <= 2)
        .collect();
    scored.sort_by_key(|(d, _)| *d);
    let mut out: Vec<String> = scored.iter().map(|(_, f)| f.to_string()).collect();
    if out.len() < 3 {
        let lname = name.to_lowercase();
        for f in FUNCTION_NAMES {
            if out.len() >= 3 {
                break;
            }
            if (f.starts_with(&lname) || lname.starts_with(f)) && !out.iter().any(|o| o == f) {
                out.push(f.to_string());
            }
        }
    }
    out.truncate(3);
    out
}

fn binary(op: &BinOp, a: &Value, b: &Value) -> Result<Value, QueryError> {
    use Value::*;
    Ok(match op {
        BinOp::Add => match (a, b) {
            (Number(x), Number(y)) => Number(x + y),
            (Array(x), Array(y)) => {
                let mut v = x.clone();
                v.extend(y.iter().cloned());
                Array(v)
            }
            (Null, other) | (other, Null) => other.clone(),
            _ => String(format!("{}{}", a.to_text(), b.to_text())),
        },
        BinOp::Sub => match (a, b) {
            (Number(x), Number(y)) => Number(x - y),
            _ => Null,
        },
        BinOp::Mul => match (a, b) {
            (Number(x), Number(y)) => Number(x * y),
            (String(s), Number(n)) | (Number(n), String(s)) => {
                if *n <= 0.0 {
                    String(std::string::String::new())
                } else {
                    String(s.repeat(*n as usize))
                }
            }
            _ => Null,
        },
        BinOp::Div => match (a, b) {
            (Number(_), Number(y)) if *y == 0.0 => return Err(QueryError::new("Division by zero")),
            (Number(x), Number(y)) => Number(x / y),
            _ => Null,
        },
        BinOp::Mod => match (a, b) {
            (Number(_), Number(y)) if *y == 0.0 => return Err(QueryError::new("Division by zero")),
            (Number(x), Number(y)) => Number(x % y),
            _ => Null,
        },
        BinOp::Eq => Bool(a.loose_eq(b)),
        BinOp::Ne => Bool(!a.loose_eq(b)),
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            let ord = match (a, b) {
                (Number(x), Number(y)) => x.partial_cmp(y),
                (String(x), String(y)) => Some(x.cmp(y)),
                _ => None,
            };
            match ord {
                None => Bool(false),
                Some(o) => Bool(match op {
                    BinOp::Lt => o.is_lt(),
                    BinOp::Le => o.is_le(),
                    BinOp::Gt => o.is_gt(),
                    _ => o.is_ge(),
                }),
            }
        }
        BinOp::And => Bool(a.truthy() && b.truthy()),
        BinOp::Or => Bool(a.truthy() || b.truthy()),
    })
}
