        out.push('\n');
    }
    out
}

pub fn render_md(results: &[Value]) -> String {
    if results.is_empty() {
        return String::new();
    }
    let parts: Vec<String> = results.iter().map(|v| v.to_markdown()).collect();
    format!("{}\n", parts.join("\n\n"))
}

pub fn render_tree(results: &[Value]) -> String {
    if results.is_empty() {
        return String::new();
    }
    let mut out = String::new();
    let n = results.len();
    for (i, v) in results.iter().enumerate() {
        render_tree_node(v, "", i + 1 == n, &mut out);
    }
    out.push('\n');
    out
}

fn render_tree_node(v: &Value, indent: &str, is_last: bool, out: &mut String) {
    let connector = if is_last { "└──" } else { "├──" };
    let child_indent = format!("{}{}", indent, if is_last { "   " } else { "│  " });
    match v {
        Value::Array(items) => {
            out.push_str(&format!("{}{}[\n", indent, connector));
            let n = items.len();
            for (i, item) in items.iter().enumerate() {
                render_tree_node(item, &child_indent, i + 1 == n, out);
            }
            out.push_str(&format!("{}]\n", child_indent));
        }
        Value::Object(map) => {
            out.push_str(&format!("{}{}{{\n", indent, connector));
            let n = map.len();
            for (i, (k, val)) in map.iter().enumerate() {
                match val {
                    Value::Array(_) | Value::Object(_) => {
                        out.push_str(&format!("{}{}: \n", child_indent, k));
                        let nested_indent = format!("{}  ", child_indent);
                        render_tree_node(val, &nested_indent, i + 1 == n, out);
                    }
                    other => {
                        out.push_str(&format!("{}{}: {}\n", child_indent, k, other.to_text()));
                    }
                }
            }
            out.push_str(&format!("{}}}\n", child_indent));
        }
        Value::Heading(h) => {
            out.push_str(&format!("{}{}{} {}\n", indent, connector, "#".repeat(h.level as usize), h.text));
        }
        other => {
            out.push_str(&format!("{}{}{}\n", indent, connector, other.to_text()));
        }
    }
}
