//! Rendering of markdown section content into styled text lines.

use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span};
use unicode_width::UnicodeWidthStr;

use super::theme::Theme;
use crate::md::blocks::{parse_blocks, Block, ListItem};
use crate::md::inline::{parse_inline, Inline};
use crate::md::inline_text::RefDefs;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Kind {
    Normal,
    Bold,
    Italic,
    Code,
    Strike,
    Link,
    Heading(u8),
    Fence,
    CodeText,
    Quote,
    Bullet,
    Rule,
    Table,
    Dim,
}

pub type RSpan = (String, Kind);
pub type RLine = Vec<RSpan>;

fn inline_spans(nodes: &[Inline]) -> Vec<RSpan> {
    let mut out = Vec::new();
    for n in nodes {
        match n {
            Inline::Text(t) => out.push((t.clone(), Kind::Normal)),
            Inline::Emphasis(t) => out.push((t.clone(), Kind::Italic)),
            Inline::Strong(t) => out.push((t.clone(), Kind::Bold)),
            Inline::Code(t) => out.push((t.clone(), Kind::Code)),
            Inline::Strikethrough(t) => out.push((t.clone(), Kind::Strike)),
            Inline::Link { text, .. } => out.push((text.clone(), Kind::Link)),
            Inline::Image { .. } => {}
        }
    }
    out
}

/// Word-wrap a sequence of spans into lines no wider than `width`.
pub fn wrap_spans(spans: &[RSpan], width: usize, indent: &str) -> Vec<RLine> {
    let width = width.max(4);
    let mut lines: Vec<RLine> = Vec::new();
    let mut cur: RLine = Vec::new();
    let mut cur_w = 0usize;
    let mut first = true;

    let push_line = |lines: &mut Vec<RLine>, cur: &mut RLine| {
        // trim trailing whitespace of last span
        if let Some(last) = cur.last_mut() {
            let trimmed = last.0.trim_end().to_string();
            last.0 = trimmed;
        }
        lines.push(std::mem::take(cur));
    };

    for (text, kind) in spans {
        // handle explicit newlines (hard breaks)
        let parts: Vec<&str> = text.split('\n').collect();
        for (pi, part) in parts.iter().enumerate() {
            if pi > 0 {
                push_line(&mut lines, &mut cur);
                cur_w = 0;
                first = false;
            }
            // split into words keeping spaces attached
            let mut word = String::new();
            let mut tokens: Vec<String> = Vec::new();
            for ch in part.chars() {
                word.push(ch);
                if ch == ' ' {
                    tokens.push(std::mem::take(&mut word));
                }
            }
            if !word.is_empty() {
                tokens.push(word);
            }
            for tok in tokens {
                let tw = UnicodeWidthStr::width(tok.trim_end());
                let avail = if first || lines.is_empty() && cur.is_empty() {
                    width
                } else {
                    width.saturating_sub(indent.len())
                };
                let _ = avail;
                if cur_w + tw > width && cur_w > 0 {
                    push_line(&mut lines, &mut cur);
                    cur_w = 0;
                    first = false;
                    if !indent.is_empty() {
                        cur.push((indent.to_string(), Kind::Normal));
                        cur_w = indent.len();
                    }
                }
                if tok.trim().is_empty() && cur_w == 0 {
                    continue;
                }
                let full_w = UnicodeWidthStr::width(tok.as_str());
                match cur.last_mut() {
                    Some(last) if last.1 == *kind => last.0.push_str(&tok),
                    _ => cur.push((tok.clone(), *kind)),
                }
                cur_w += full_w;
            }
        }
    }
    if !cur.is_empty() || lines.is_empty() {
        push_line(&mut lines, &mut cur);
    }
    lines
}

fn render_list(items: &[ListItem], ordered: bool, start: u64, depth: usize, width: usize, out: &mut Vec<RLine>) {
    let indent = "  ".repeat(depth + 1);
    for (i, item) in items.iter().enumerate() {
        let marker = match item.checked {
            Some(true) => "☑ ".to_string(),
            Some(false) => "☐ ".to_string(),
            None => {
                if ordered {
                    format!("{}. ", start.max(1) + i as u64)
                } else {
                    "• ".to_string()
                }
            }
        };
        // first line + plain continuation lines
        let mut plain: Vec<String> = Vec::new();
        let mut nested: Vec<String> = Vec::new();
        for (li, l) in item.raw_lines.iter().enumerate() {
            if li > 0 && l.starts_with(' ') {
                nested.push(l.clone());
            } else if nested.is_empty() {
                plain.push(l.clone());
            } else {
                nested.push(l.clone());
            }
        }
        let text = plain.join("\n");
        let refs = RefDefs::default();
        let mut spans: Vec<RSpan> = vec![(indent.clone(), Kind::Normal), (marker.clone(), Kind::Bullet)];
        spans.extend(inline_spans(&parse_inline(&text, &refs)));
        let cont_indent = " ".repeat(indent.len() + UnicodeWidthStr::width(marker.as_str()));
        out.extend(wrap_spans(&spans, width, &cont_indent));
        for n in &nested {
            let ws_len = n.len() - n.trim_start().len();
            let level = depth + 1 + ws_len / 2;
            let nested_indent = "  ".repeat(level + 1);
            let t = n.trim();
            let (m, body) = if let Some(r) = t.strip_prefix("[ ]") {
                ("☐ ".to_string(), r.trim_start())
            } else if let Some(r) = t.strip_prefix("[x]").or_else(|| t.strip_prefix("[X]")) {
                ("☑ ".to_string(), r.trim_start())
            } else {
                ("• ".to_string(), t)
            };
            let mut spans: Vec<RSpan> = vec![(nested_indent.clone(), Kind::Normal), (m.clone(), Kind::Bullet)];
            spans.extend(inline_spans(&parse_inline(body, &refs)));
            let ci = " ".repeat(nested_indent.len() + 2);
            out.extend(wrap_spans(&spans, width, &ci));
        }
        for b in &item.blocks {
            render_block(b, width, depth + 1, out);
        }
    }
}

fn render_table(headers: &[String], rows: &[Vec<String>], out: &mut Vec<RLine>) {
    let cols = headers.len().max(rows.iter().map(|r| r.len()).max().unwrap_or(0));
    if cols == 0 {
        return;
    }
    let mut widths = vec![0usize; cols];
    for (i, h) in headers.iter().enumerate() {
        widths[i] = widths[i].max(UnicodeWidthStr::width(h.as_str()));
    }
    for r in rows {
        for (i, c) in r.iter().enumerate() {
            if i < cols {
                widths[i] = widths[i].max(UnicodeWidthStr::width(c.as_str()));
            }
        }
    }
    let border = |l: &str, m: &str, r: &str| -> RLine {
        let mut s = String::from(l);
        for (i, w) in widths.iter().enumerate() {
            s.push_str(&"─".repeat(w + 2));
            s.push_str(if i + 1 == widths.len() { r } else { m });
        }
        vec![(s, Kind::Table)]
    };
    let row_line = |cells: &[String]| -> RLine {
        let mut spans: RLine = vec![("│".to_string(), Kind::Table)];
        for (i, w) in widths.iter().enumerate() {
            let c = cells.get(i).cloned().unwrap_or_default();
            let pad = w.saturating_sub(UnicodeWidthStr::width(c.as_str()));
            spans.push((format!(" {}{} ", c, " ".repeat(pad)), Kind::Normal));
            spans.push(("│".to_string(), Kind::Table));
        }
        spans
    };
    out.push(border("┌", "┬", "┐"));
    out.push(row_line(headers));
    out.push(border("├", "┼", "┤"));
    for r in rows {
        out.push(row_line(r));
    }
    out.push(border("└", "┴", "┘"));
}

fn render_block(block: &Block, width: usize, depth: usize, out: &mut Vec<RLine>) {
    match block {
        Block::Heading { level, inline, .. } => {
            let text = crate::md::inline::inline_plain(inline);
            out.push(vec![(text, Kind::Heading(*level))]);
        }
        Block::Paragraph { inline } => {
            let spans = inline_spans(inline);
            if spans.iter().all(|s| s.0.trim().is_empty()) {
                out.push(vec![]);
            } else {
                out.extend(wrap_spans(&spans, width, ""));
            }
        }
        Block::QuoteSpill { inline } => {
            for _ in inline {
                out.push(vec![]);
            }
        }
        Block::Code { language, content } => {
            out.push(vec![(format!("```{}", language.clone().unwrap_or_default()), Kind::Fence)]);
            for l in content.lines() {
                out.push(vec![(l.to_string(), Kind::CodeText)]);
            }
            out.push(vec![("```".to_string(), Kind::Fence)]);
        }
        Block::List { ordered, items, start } => render_list(items, *ordered, *start, depth, width, out),
        Block::Table { headers, rows, .. } => render_table(headers, rows, out),
        Block::BlockQuote { inline, .. } => {
            let text = crate::md::inline::inline_plain(inline);
            let spans = vec![("│ ".to_string(), Kind::Quote), (text, Kind::Quote)];
            out.extend(wrap_spans(&spans, width, "│ "));
        }
        Block::HorizontalRule => out.push(vec![("─".repeat(60.min(width)), Kind::Rule)]),
        Block::Html { .. } => {}
    }
}

/// Render a section's markdown content into styled lines.
pub fn render_content(content: &str, refs: &RefDefs, width: usize) -> Vec<RLine> {
    let blocks = parse_blocks(content, refs);
    let mut out: Vec<RLine> = Vec::new();
    for (i, b) in blocks.iter().enumerate() {
        if i > 0 {
            out.push(vec![]);
        }
        render_block(b, width, 0, &mut out);
    }
    out
}

/// Render raw source lines with line numbers.
pub fn render_raw(raw: &str, first_line_no: usize) -> Vec<RLine> {
    raw.lines()
        .enumerate()
        .map(|(i, l)| vec![(format!("{:>4} │ ", first_line_no + i), Kind::Dim), (l.to_string(), Kind::Normal)])
        .collect()
}

pub fn style_for(kind: Kind, theme: &Theme) -> Style {
    let base = Style::default().fg(theme.fg);
    match kind {
        Kind::Normal => base,
        Kind::Bold => base.add_modifier(Modifier::BOLD),
        Kind::Italic => Style::default().fg(theme.emphasis).add_modifier(Modifier::ITALIC),
        Kind::Code => Style::default().fg(theme.code),
        Kind::Strike => base.add_modifier(Modifier::CROSSED_OUT),
        Kind::Link => Style::default().fg(theme.link).add_modifier(Modifier::UNDERLINED),
        Kind::Heading(l) => Style::default()
            .fg(theme.heading[(l.clamp(1, 6) - 1) as usize])
            .add_modifier(Modifier::BOLD),
        Kind::Fence => Style::default().fg(theme.code_fence),
        Kind::CodeText => Style::default().fg(theme.code),
        Kind::Quote => Style::default().fg(theme.quote).add_modifier(Modifier::ITALIC),
        Kind::Bullet => Style::default().fg(theme.bullet),
        Kind::Rule => Style::default().fg(theme.border_inactive),
        Kind::Table => Style::default().fg(theme.border_inactive),
        Kind::Dim => Style::default().fg(theme.border_inactive),
    }
}

pub fn to_line(rl: &RLine, theme: &Theme, highlight: Option<&str>) -> Line<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    for (text, kind) in rl {
        let style = style_for(*kind, theme);
        match highlight {
            Some(q) if !q.is_empty() => {
                let lower = text.to_lowercase();
                let ql = q.to_lowercase();
                let mut pos = 0;
                while let Some(idx) = lower[pos..].find(&ql) {
                    let s = pos + idx;
                    if s > pos {
                        spans.push(Span::styled(text[pos..s].to_string(), style));
                    }
                    spans.push(Span::styled(
                        text[s..s + ql.len()].to_string(),
                        Style::default().fg(ratatui::style::Color::Black).bg(ratatui::style::Color::Yellow),
                    ));
                    pos = s + ql.len();
                    if pos >= text.len() {
                        break;
                    }
                }
                if pos < text.len() {
                    spans.push(Span::styled(text[pos..].to_string(), style));
                }
            }
            _ => spans.push(Span::styled(text.clone(), style)),
        }
    }
    Line::from(spans)
}
