fn list_markdown_files(dir: &Path) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = match std::fs::read_dir(dir) {
        Ok(rd) => rd
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .filter(|p| {
                p.is_file()
                    && p
                        .extension()
                        .and_then(|e| e.to_str())
                        .map(|e| matches!(e.to_lowercase().as_str(), "md" | "markdown"))
                        .unwrap_or(false)
            })
            .collect(),
        Err(_) => Vec::new(),
    };
    files.sort_by(|a, b| {
        a.file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .to_lowercase()
            .cmp(&b.file_name().unwrap_or_default().to_string_lossy().to_lowercase())
    });
    files
}

impl App {
    fn new(doc: Document, label: String, path: Option<PathBuf>, config: Config, theme_idx: usize) -> App {
        let n = doc.headings.len();
        let tree = build_tree(&doc.headings);
        let mut has_children = vec![false; n];
        fn mark(nodes: &[HeadingNode], hc: &mut Vec<bool>) {
            for n in nodes {
                hc[n.idx] = !n.children.is_empty();
                mark(&n.children, hc);
            }
        }
        mark(&tree, &mut has_children);
        let outline_width = config.outline_width;
        let mut app = App {
            doc,
            file_label: label,
            file_path: path,
            expanded: vec![true; n],
            has_children,
            rows: Vec::new(),
            selected: 0,
            outline_scroll: 0,
            focus: Focus::Outline,
            mode: Mode::Normal,
            content_scroll: 0,
            content_cache: None,
            outline_width,
            show_outline: true,
            theme_idx,
            raw_view: false,
            search_input: String::new(),
            search_query: String::new(),
            filter_input: String::new(),
            filter_active: false,
            todo_filter: false,
            help_scroll: 0,
            message: None,
            picker_files: Vec::new(),
            picker_selected: 0,
            picker_filter: String::new(),
            palette_input: String::new(),
            palette_selected: 0,
            bookmark: None,
            count_prefix: String::new(),
            config,
            history: Vec::new(),
            quit: false,
        };
        app.rebuild_rows();
        app
    }

    fn theme(&self) -> &'static Theme {
        &THEMES[self.theme_idx % THEMES.len()]
    }

    fn load_document(&mut self, doc: Document, label: String, path: Option<PathBuf>) {
        let n = doc.headings.len();
        let tree = build_tree(&doc.headings);
        let mut has_children = vec![false; n];
        fn mark(nodes: &[HeadingNode], hc: &mut Vec<bool>) {
            for n in nodes {
                hc[n.idx] = !n.children.is_empty();
                mark(&n.children, hc);
            }
        }
        mark(&tree, &mut has_children);
        self.doc = doc;
        self.file_label = label;
        self.file_path = path;
        self.expanded = vec![true; n];
        self.has_children = has_children;
        self.selected = 0;
        self.outline_scroll = 0;
        self.content_scroll = 0;
        self.content_cache = None;
        self.search_query.clear();
        self.filter_active = false;
        self.filter_input.clear();
        self.rebuild_rows();
    }

    /// Recompute the visible outline rows (respecting collapsed nodes and filters).
    fn rebuild_rows(&mut self) {
        let prev_idx = self.rows.get(self.selected).map(|r| r.idx);
        self.rows.clear();
        let headings = &self.doc.headings;
        let filter = if self.filter_active || self.mode == Mode::Filter {
            self.filter_input.to_lowercase()
        } else {
            String::new()
        };
        let mut collapsed_level: Option<u8> = None;
        for (i, h) in headings.iter().enumerate() {
            if let Some(cl) = collapsed_level {
                if h.level > cl {
                    continue;
                }
                collapsed_level = None;
            }
            let mut visible = true;
            if !filter.is_empty() && !h.text.to_lowercase().contains(&filter) {
                visible = false;
            }
            if self.todo_filter && !self.doc.section_content(i).contains("- [ ]") {
                visible = false;
            }
            if visible {
                self.rows.push(OutlineRow { idx: i });
            }
            if !self.expanded[i] && self.has_children[i] && filter.is_empty() && !self.todo_filter {
                collapsed_level = Some(h.level);
            }
        }
        if let Some(pi) = prev_idx {
            if let Some(pos) = self.rows.iter().position(|r| r.idx == pi) {
                self.selected = pos;
            } else {
                self.selected = self.selected.min(self.rows.len().saturating_sub(1));
            }
        } else {
            self.selected = 0;
        }
    }

    fn current_heading(&self) -> Option<usize> {
        self.rows.get(self.selected).map(|r| r.idx)
    }

    fn content_lines(&mut self, width: usize) -> Vec<RLine> {
        let idx = self.current_heading();
        let key = (idx.unwrap_or(usize::MAX), width, self.raw_view);
        if let Some((i, w, r, lines)) = &self.content_cache {
            if (*i, *w, *r) == key {
                return lines.clone();
            }
        }
        let lines = match idx {
            Some(i) => {
                if self.raw_view {
                    let raw = self.doc.section_raw_md(i).to_string();
                    let first_line = self.doc.source[..self.doc.headings[i].offset].matches('\n').count() + 1;
                    render_raw(&raw, first_line)
                } else {
                    let content = self.doc.section_content(i).to_string();
                    render_content(&content, &self.doc.refs, width)
                }
            }
            None => Vec::new(),
        };
        self.content_cache = Some((key.0, key.1, key.2, lines.clone()));
        lines
    }

    fn move_selection(&mut self, delta: i64) {
        if self.rows.is_empty() {
            return;
        }
        let n = self.rows.len() as i64;
        let new = (self.selected as i64 + delta).clamp(0, n - 1);
        if new as usize != self.selected {
            self.selected = new as usize;
            self.content_scroll = 0;
        }
    }

    fn toggle_expand(&mut self) {
        if let Some(i) = self.current_heading() {
            if self.has_children[i] {
                self.expanded[i] = !self.expanded[i];
                self.rebuild_rows();
            }
        }
    }

    fn set_expand(&mut self, value: bool) {
        if let Some(i) = self.current_heading() {
            if self.has_children[i] {
                if self.expanded[i] != value {
                    self.expanded[i] = value;
                    self.rebuild_rows();
                }
            } else if !value {
                self.jump_to_parent();
            }
        }
    }

    fn jump_to_parent(&mut self) {
        if let Some(i) = self.current_heading() {
            let level = self.doc.headings[i].level;
            let mut j = i;
            while j > 0 {
                j -= 1;
                if self.doc.headings[j].level < level {
                    if let Some(pos) = self.rows.iter().position(|r| r.idx == j) {
                        self.selected = pos;
                        self.content_scroll = 0;
                    }
                    return;
                }
            }
        }
    }

    fn search_matches(&self) -> Vec<usize> {
        if self.search_query.is_empty() {
            return Vec::new();
        }
        let q = self.search_query.to_lowercase();
        self.doc
            .headings
            .iter()
            .enumerate()
            .filter(|(i, h)| {
                h.text.to_lowercase().contains(&q) || self.doc.section_content(*i).to_lowercase().contains(&q)
            })
            .map(|(i, _)| i)
            .collect()
    }

    fn goto_heading(&mut self, idx: usize) {
        // expand ancestors
        let level = self.doc.headings[idx].level;
        let mut lvl = level;
        let mut j = idx;
        while j > 0 && lvl > 1 {
            j -= 1;
            if self.doc.headings[j].level < lvl {
                self.expanded[j] = true;
                lvl = self.doc.headings[j].level;
            }
        }
        self.rebuild_rows();
        if let Some(pos) = self.rows.iter().position(|r| r.idx == idx) {
            self.selected = pos;
            self.content_scroll = 0;
        }
    }

    fn next_match(&mut self, forward: bool) {
        let matches = self.search_matches();
        if matches.is_empty() {
            self.message = Some("No matches".to_string());
            return;
        }
        let cur = self.current_heading().unwrap_or(0);
        let target = if forward {
            matches.iter().find(|&&m| m > cur).or(matches.first())
        } else {
            matches.iter().rev().find(|&&m| m < cur).or(matches.last())
        };
        if let Some(&t) = target {
            self.goto_heading(t);
        }
    }

    fn open_file(&mut self, path: PathBuf) {
        match std::fs::read_to_string(&path) {
            Ok(content) => {
                let content = normalize_input(&content);
                let doc = Document::parse(&content);
                let label = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                if let Some(cur) = self.file_path.clone() {
                    self.history.push(cur);
                }
                self.load_document(doc, label, Some(path));
                self.mode = Mode::Normal;
            }
            Err(e) => {
                self.message = Some(format!("Failed to open file: {}", e));
            }
        }
    }

    fn handle_key(&mut self, key: KeyEvent, visible_height: usize) {
        if key.kind != KeyEventKind::Press && key.kind != KeyEventKind::Repeat {
            return;
        }
        self.message = None;
        match self.mode {
            Mode::Help => self.handle_help_key(key),
            Mode::Search => self.handle_search_key(key),
            Mode::Filter => self.handle_filter_key(key),
            Mode::Picker => self.handle_picker_key(key),
            Mode::Palette => self.handle_palette_key(key),
            Mode::Interactive | Mode::Links => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => self.mode = Mode::Normal,
                _ => {}
            },
            Mode::Normal => self.handle_normal_key(key, visible_height),
        }
    }

    fn handle_help_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Esc | KeyCode::Char('?') | KeyCode::Char('q') => self.mode = Mode::Normal,
            KeyCode::Char('j') | KeyCode::Down => self.help_scroll += 1,
            KeyCode::Char('k') | KeyCode::Up => self.help_scroll = self.help_scroll.saturating_sub(1),
            KeyCode::Char('g') => self.help_scroll = 0,
            KeyCode::Char('G') => self.help_scroll = HELP_TEXT.lines().count().saturating_sub(1),
            _ => {}
        }
    }

    fn handle_search_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Esc => {
                self.search_input.clear();
                self.search_query.clear();
                self.mode = Mode::Normal;
            }
            KeyCode::Enter => {
                self.search_query = self.search_input.clone();
                self.mode = Mode::Normal;
                if !self.search_query.is_empty() {
                    let matches = self.search_matches();
                    if let Some(&m) = matches.first() {
                        self.goto_heading(m);
                    } else {
                        self.message = Some("No matches".to_string());
                    }
                }
            }
            KeyCode::Tab => {
                self.mode = Mode::Filter;
                self.filter_input = std::mem::take(&mut self.search_input);
                self.rebuild_rows();
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => self.search_input.clear(),
            KeyCode::Backspace => {
                self.search_input.pop();
            }
            KeyCode::Char(c) => self.search_input.push(c),
            _ => {}
        }
    }

    fn handle_filter_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Esc => {
                self.filter_input.clear();
                self.filter_active = false;
                self.mode = Mode::Normal;
                self.rebuild_rows();
            }
            KeyCode::Enter => {
                self.filter_active = !self.filter_input.is_empty();
                self.mode = Mode::Normal;
                self.rebuild_rows();
            }
            KeyCode::Tab => {
                self.mode = Mode::Search;
                self.search_input = std::mem::take(&mut self.filter_input);
                self.rebuild_rows();
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.filter_input.clear();
                self.rebuild_rows();
            }
            KeyCode::Backspace => {
                self.filter_input.pop();
                self.rebuild_rows();
            }
            KeyCode::Char(c) => {
                self.filter_input.push(c);
                self.rebuild_rows();
            }
            _ => {}
        }
    }

    fn filtered_picker(&self) -> Vec<usize> {
        let q = self.picker_filter.to_lowercase();
        self.picker_files
            .iter()
            .enumerate()
            .filter(|(_, p)| q.is_empty() || p.to_string_lossy().to_lowercase().contains(&q))
            .map(|(i, _)| i)
            .collect()
    }

    fn handle_picker_key(&mut self, key: KeyEvent) {
        let visible = self.filtered_picker();
        match key.code {
            KeyCode::Esc => {
                if !self.picker_filter.is_empty() {
                    self.picker_filter.clear();
                } else {
                    self.mode = Mode::Normal;
                }
            }
            KeyCode::Char('q') if self.picker_filter.is_empty() => self.quit = true,
            KeyCode::Char('j') | KeyCode::Down => {
                if self.picker_selected + 1 < visible.len() {
                    self.picker_selected += 1;
                }
            }
            KeyCode::Char('k') | KeyCode::Up => self.picker_selected = self.picker_selected.saturating_sub(1),
            KeyCode::Char('g') => self.picker_selected = 0,
            KeyCode::Char('G') => self.picker_selected = visible.len().saturating_sub(1),
            KeyCode::Enter => {
                if let Some(&i) = visible.get(self.picker_selected) {
                    let path = self.picker_files[i].clone();
                    self.open_file(path);
                }
            }
            KeyCode::Char('/') => {}
            KeyCode::Backspace => {
                self.picker_filter.pop();
                self.picker_selected = 0;
            }
            KeyCode::Char(c) if c.is_ascii_digit() && self.picker_filter.is_empty() => {
                let n = c.to_digit(10).unwrap_or(0) as usize;
                if n >= 1 && n <= visible.len() {
                    let path = self.picker_files[visible[n - 1]].clone();
                    self.open_file(path);
                }
            }
            KeyCode::Char(c) => {
                self.picker_filter.push(c);
                self.picker_selected = 0;
            }
            _ => {}
        }
    }

    fn filtered_palette(&self) -> Vec<usize> {
        let q = self.palette_input.to_lowercase();
        PALETTE_COMMANDS
            .iter()
            .enumerate()
            .filter(|(_, (name, aliases, _))| {
                q.is_empty() || name.to_lowercase().contains(&q) || aliases.to_lowercase().contains(&q)
            })
            .map(|(i, _)| i)
            .collect()
    }

    fn handle_palette_key(&mut self, key: KeyEvent) {
        let visible = self.filtered_palette();
        match key.code {
            KeyCode::Esc => self.mode = Mode::Normal,
            KeyCode::Down | KeyCode::Tab => {
                if self.palette_selected + 1 < visible.len() {
                    self.palette_selected += 1;
                }
            }
            KeyCode::Up | KeyCode::BackTab => self.palette_selected = self.palette_selected.saturating_sub(1),
            KeyCode::Enter => {
                if let Some(&i) = visible.get(self.palette_selected) {
                    self.mode = Mode::Normal;
                    self.run_palette_command(i);
                }
            }
            KeyCode::Backspace => {
                self.palette_input.pop();
                self.palette_selected = 0;
            }
            KeyCode::Char(c) => {
                self.palette_input.push(c);
                self.palette_selected = 0;
            }
            _ => {}
        }
    }

    fn run_palette_command(&mut self, i: usize) {
        match PALETTE_COMMANDS[i].0 {
            "Save changes" => self.message = Some("No pending changes".to_string()),
            "Undo edit" => self.message = Some("Nothing to undo".to_string()),
            "Save width to config" => self.save_width(),
            "Toggle outline" => self.show_outline = !self.show_outline,
            "Toggle help" => {
                self.mode = Mode::Help;
                self.help_scroll = 0;
            }
            "Toggle raw source" => self.toggle_raw(),
            "Jump to top" => {
                self.selected = 0;
                self.content_scroll = 0;
            }
            "Jump to bottom" => {
                self.selected = self.rows.len().saturating_sub(1);
                self.content_scroll = 0;
            }
            "Cycle theme" => self.cycle_theme(),
            "Quit" => self.quit = true,
            _ => {}
        }
    }

    fn toggle_raw(&mut self) {
        self.raw_view = !self.raw_view;
        self.content_scroll = 0;
        self.message = Some(if self.raw_view {
            "Raw source view enabled".to_string()
        } else {
            "Raw source view disabled".to_string()
        });
    }

    fn cycle_theme(&mut self) {
        self.theme_idx = (self.theme_idx + 1) % THEMES.len();
        self.config.theme = self.theme().id.to_string();
        let _ = self.config.save();
        self.message = Some(format!("Theme: {}", self.theme().name));
    }

    fn save_width(&mut self) {
        self.config.outline_width = self.outline_width;
        match self.config.save() {
            Ok(_) => self.message = Some(format!("Saved outline width {}% to config", self.outline_width)),
            Err(e) => self.message = Some(format!("Failed to save config: {}", e)),
        }
    }

    fn handle_normal_key(&mut self, key: KeyEvent, visible_height: usize) {
        // vim-style count prefix
        if let KeyCode::Char(c) = key.code {
            if c.is_ascii_digit() && !(c == '0' && self.count_prefix.is_empty()) {
                self.count_prefix.push(c);
                return;
            }
        }
        let count: i64 = self.count_prefix.parse().unwrap_or(1);
        self.count_prefix.clear();

        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => {
                if key.code == KeyCode::Esc && (!self.search_query.is_empty() || self.filter_active) {
                    self.search_query.clear();
                    self.filter_active = false;
                    self.filter_input.clear();
                    self.rebuild_rows();
                } else {
                    self.quit = true;
                }
            }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => self.quit = true,
            KeyCode::Char('?') => {
                self.mode = Mode::Help;
                self.help_scroll = 0;
            }
            KeyCode::Tab => {
                self.focus = if self.focus == Focus::Outline { Focus::Content } else { Focus::Outline };
            }
            KeyCode::Char('j') | KeyCode::Down => {
                if self.focus == Focus::Outline {
                    self.move_selection(count);
                } else {
                    self.content_scroll += count as usize;
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.focus == Focus::Outline {
                    self.move_selection(-count);
                } else {
                    self.content_scroll = self.content_scroll.saturating_sub(count as usize);
                }
            }
            KeyCode::Char('g') | KeyCode::Home => {
                if self.focus == Focus::Outline {
                    self.selected = 0;
                    self.content_scroll = 0;
                } else {
                    self.content_scroll = 0;
                }
            }
            KeyCode::Char('G') | KeyCode::End => {
                if self.focus == Focus::Outline {
                    self.selected = self.rows.len().saturating_sub(1);
                    self.content_scroll = 0;
                } else {
                    self.content_scroll = usize::MAX / 2;
                }
            }
            KeyCode::Char('d') | KeyCode::PageDown => {
                self.content_scroll += visible_height.max(1);
            }
            KeyCode::Char('u') | KeyCode::PageUp => {
                self.content_scroll = self.content_scroll.saturating_sub(visible_height.max(1));
            }
            KeyCode::Enter | KeyCode::Char(' ') => {
                if self.focus == Focus::Outline {
                    self.toggle_expand();
                }
            }
            KeyCode::Char('l') | KeyCode::Right => self.set_expand(true),
            KeyCode::Char('h') | KeyCode::Left => self.set_expand(false),
            KeyCode::Char('p') => self.jump_to_parent(),
            KeyCode::Char('/') => {
                self.mode = Mode::Search;
                self.search_input = self.search_query.clone();
            }
            KeyCode::Char('s') => {
                self.mode = Mode::Filter;
                self.rebuild_rows();
            }
            KeyCode::Char('n') => self.next_match(true),
            KeyCode::Char('N') => self.next_match(false),
            KeyCode::Char('r') => self.toggle_raw(),
            KeyCode::Char('w') => self.show_outline = !self.show_outline,
            KeyCode::Char(']') => {
                self.outline_width = match self.outline_width {
                    20 => 30,
                    30 => 40,
                    _ => 20,
                };
                self.message = Some(format!("Width: {}%", self.outline_width));
            }
            KeyCode::Char('[') => {
                self.outline_width = match self.outline_width {
                    40 => 30,
                    30 => 20,
                    _ => 40,
                };
                self.message = Some(format!("Width: {}%", self.outline_width));
            }
            KeyCode::Char('S') => self.save_width(),
            KeyCode::Char(':') => {
                self.mode = Mode::Palette;
                self.palette_input.clear();
                self.palette_selected = 0;
            }
            KeyCode::Char('m') => {
                self.bookmark = self.current_heading();
                self.message = Some("Bookmark set".to_string());
            }
            KeyCode::Char('\'') => {
                if let Some(b) = self.bookmark {
                    self.goto_heading(b);
                } else {
                    self.message = Some("No bookmark set".to_string());
                }
            }
            KeyCode::Char('t') => {
                self.todo_filter = !self.todo_filter;
                self.rebuild_rows();
                let msg = if self.todo_filter {
                    format!("Todo filter ON: {} headings with open todos", self.rows.len())
                } else {
                    "Todo filter OFF: showing all headings".to_string()
                };
                self.message = Some(msg);
            }
            KeyCode::Char('T') => self.cycle_theme(),
            KeyCode::Char('i') => {
                self.mode = Mode::Interactive;
                self.message = Some("⚠ No interactive elements in this section".to_string());
            }
            KeyCode::Char('f') => {
                self.mode = Mode::Links;
                self.message = Some("No links in this section".to_string());
            }
            KeyCode::Char('b') | KeyCode::Backspace => {
                if let Some(prev) = self.history.pop() {
                    match std::fs::read_to_string(&prev) {
                        Ok(content) => {
                            let doc = Document::parse(&normalize_input(&content));
                            let label = prev.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                            self.load_document(doc, label, Some(prev));
                        }
                        Err(e) => self.message = Some(format!("Failed to open file: {}", e)),
                    }
                } else {
                    self.message = Some("No previous file".to_string());
                }
            }
            KeyCode::Char('y') => self.message = Some("Copied section content".to_string()),
            KeyCode::Char('Y') => self.message = Some("Copied anchor link".to_string()),
            KeyCode::Char('e') => self.message = Some("No editor configured ($VISUAL or $EDITOR)".to_string()),
            KeyCode::Char('o') => {
                if let Some(dir) = self.file_path.as_ref().and_then(|p| p.parent().map(|d| d.to_path_buf())) {
                    self.picker_files = list_markdown_files(&dir);
                    self.picker_selected = 0;
                    self.picker_filter.clear();
                    self.mode = Mode::Picker;
                }
            }
            _ => {}
        }
    }
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn draw(frame: &mut Frame, app: &mut App) -> usize {
    let theme = app.theme();
    let area = frame.area();
    frame.render_widget(WBlock::default().style(Style::default().bg(theme.bg).fg(theme.fg)), area);

    let has_bar = matches!(app.mode, Mode::Search | Mode::Filter);
    let mut constraints = vec![Constraint::Length(1), Constraint::Length(1)];
    if has_bar {
        constraints.push(Constraint::Length(3));
    }
    constraints.push(Constraint::Min(3));
    constraints.push(Constraint::Length(1));
    constraints.push(Constraint::Length(1));
    let chunks = Layout::default().direction(Direction::Vertical).constraints(constraints).split(area);

    // Title
    let title = format!("treemd - {} - {} headings", app.file_label, app.doc.headings.len());
    frame.render_widget(
        Paragraph::new(Line::from(Span::styled(
            title,
            Style::default().fg(theme.title).add_modifier(Modifier::BOLD),
        ))),
        chunks[0],
    );
    frame.render_widget(
        Paragraph::new(Line::from(Span::styled(
            "─".repeat(area.width as usize),
            Style::default().fg(theme.border_inactive),
        ))),
        chunks[1],
    );

    let mut next = 2;
    if has_bar {
        let (title, label, input) = if app.mode == Mode::Search {
            (" Content Search (Tab: switch to Outline) ", "Find", &app.search_input)
        } else {
            (" Outline Search (Tab: switch to Content) ", "Filter", &app.filter_input)
        };
        let block = WBlock::default()
            .borders(Borders::ALL)
            .title(title)
            .border_style(Style::default().fg(theme.border_active));
        let text = Line::from(vec![
            Span::styled(format!("{}: ", label), Style::default().fg(theme.fg)),
            Span::styled(input.clone(), Style::default().fg(theme.title)),
            Span::styled("_", Style::default().fg(theme.title)),
            Span::styled("  (Esc, Ctrl+U)", Style::default().fg(theme.border_inactive)),
        ]);
        frame.render_widget(Paragraph::new(text).block(block), chunks[next]);
        next += 1;
    }
    let main = chunks[next];
    let status_area = chunks[next + 1];
    let hints_area = chunks[next + 2];

    let (outline_area, content_area) = if app.show_outline {
        let h = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(app.outline_width), Constraint::Min(10)])
            .split(main);
        (Some(h[0]), h[1])
    } else {
        (None, main)
    };

    let visible_height = content_area.height.saturating_sub(2) as usize;

    // Outline pane
    if let Some(oa) = outline_area {
        let focused = app.focus == Focus::Outline;
        let block = WBlock::default()
            .borders(Borders::ALL)
            .title(" Outline ")
            .border_style(Style::default().fg(if focused { theme.border_active } else { theme.border_inactive }));
        let inner = block.inner(oa);
        frame.render_widget(block, oa);
        let height = inner.height as usize;
        if app.selected < app.outline_scroll {
            app.outline_scroll = app.selected;
        } else if height > 0 && app.selected >= app.outline_scroll + height {
            app.outline_scroll = app.selected + 1 - height;
        }
        let mut lines: Vec<Line> = Vec::new();
        let text_width = inner.width.saturating_sub(1) as usize;
        for (ri, row) in app.rows.iter().enumerate().skip(app.outline_scroll).take(height) {
            let h = &app.doc.headings[row.idx];
            let marker = if ri == app.selected { "► " } else { "  " };
            let indent = "  ".repeat((h.level as usize).saturating_sub(1));
            let indicator = if app.has_children[row.idx] {
                if app.expanded[row.idx] {
                    "▼ "
                } else {
                    "▶ "
                }
            } else {
                "  "
            };
            let bookmark = if app.bookmark == Some(row.idx) { "⚑ " } else { "" };
            let text = format!("{}{} {}", "#".repeat(h.level as usize), bookmark, h.text);
            let text = format!("{}{}", "#".repeat(h.level as usize), &text[h.level as usize..]);
            let mut full = format!("{}{}{}{}", marker, indent, indicator, text);
            let w = unicode_width::UnicodeWidthStr::width(full.as_str());
            if w < text_width {
                full.push_str(&" ".repeat(text_width - w));
            }
            let style = if ri == app.selected {
                Style::default()
                    .fg(theme.selected_fg)
                    .bg(theme.selected_bg)
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(theme.heading[(h.level.clamp(1, 6) - 1) as usize])
            };
            lines.push(Line::from(Span::styled(full, style)));
        }
        let list_area = Rect { x: inner.x, y: inner.y, width: inner.width.saturating_sub(1), height: inner.height };
        frame.render_widget(Paragraph::new(lines), list_area);
        let mut sb_state = ScrollbarState::new(app.rows.len().max(1)).position(app.selected);
        frame.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight)
                .begin_symbol(Some("↑"))
                .end_symbol(Some("↓"))
                .track_symbol(Some("║"))
                .thumb_symbol("█")
                .style(Style::default().fg(theme.scrollbar)),
            inner,
            &mut sb_state,
        );
    }

    // Content pane
    {
        let focused = app.focus == Focus::Content;
        let heading_text = app
            .current_heading()
            .map(|i| app.doc.headings[i].text.clone())
            .unwrap_or_default();
        let title = if app.raw_view { format!(" [RAW] {} ", heading_text) } else { format!(" {} ", heading_text) };
        let block = WBlock::default()
            .borders(Borders::ALL)
            .title(title)
            .border_style(Style::default().fg(if focused { theme.border_active } else { theme.border_inactive }));
        let inner = block.inner(content_area);
        frame.render_widget(block, content_area);
        let width = inner.width.saturating_sub(1) as usize;
        let lines = app.content_lines(width);
        let total = lines.len();
        let height = inner.height as usize;
        let max_scroll = total.saturating_sub(height);
        if app.content_scroll > max_scroll {
            app.content_scroll = max_scroll;
        }
        let query = if app.search_query.is_empty() { None } else { Some(app.search_query.as_str()) };
        let rendered: Vec<Line> = lines
            .iter()
            .skip(app.content_scroll)
            .take(height)
            .map(|l| to_line(l, theme, query))
            .collect();
        let text_area = Rect { x: inner.x, y: inner.y, width: inner.width.saturating_sub(1), height: inner.height };
        frame.render_widget(Paragraph::new(rendered), text_area);
        let mut sb_state = ScrollbarState::new(total.max(1)).position(app.content_scroll);
        frame.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight)
                .begin_symbol(Some("↑"))
                .end_symbol(Some("↓"))
                .track_symbol(Some("║"))
                .thumb_symbol("█")
                .style(Style::default().fg(theme.scrollbar)),
            inner,
            &mut sb_state,
        );

        // Status bar
        let status = if let Some(msg) = &app.message {
            msg.clone()
        } else {
            let pos = match app.focus {
                Focus::Outline => {
                    let n = app.rows.len();
                    let pct = if n == 0 { 0 } else { (app.selected + 1) * 100 / n };
                    format!("[Outline] {}/{} ({}%)", if n == 0 { 0 } else { app.selected + 1 }, n, pct)
                }
                Focus::Content => {
                    let pct = if total <= height { 100 } else { (app.content_scroll + height) * 100 / total.max(1) };
                    format!("[Content] Line {} ({}%)", app.content_scroll + 1, pct.min(100))
                }
            };
            format!(" {} • Outline:{}% • Theme:{}", pos, app.outline_width, theme.name)
        };
        frame.render_widget(
            Paragraph::new(Line::from(Span::styled(status, Style::default().fg(theme.status)))),
            status_area,
        );

        // Hints
        let hints: &[(&str, &str)] = match app.mode {
            Mode::Search | Mode::Filter => {
                &[("n/N", "Next/Prev"), ("Tab", "Outline Search"), ("Enter", "Accept"), ("Esc", "Cancel")]
            }
            Mode::Interactive => &[("j/k", "Navigate"), ("Enter", "Action"), ("Esc", "Exit")],
            Mode::Links => &[("Tab", "Next link"), ("Enter", "Follow"), ("Esc", "Exit")],
            Mode::Palette | Mode::Picker => &[("j/k", "Navigate"), ("Enter", "Select"), ("Esc", "Cancel")],
            _ => {
                if app.focus == Focus::Content {
                    &[("j/k", "Scroll"), ("/", "Search"), ("i", "Interactive"), ("f", "Links"), ("y", "Copy"), ("?", "Help")]
                } else {
                    &[("j/k", "Navigate"), ("Enter", "Select"), ("/", "Search"), ("i", "Interactive"), ("f", "Links"), ("?", "Help")]
                }
            }
        };
        let mut spans = vec![Span::raw(" ")];
        for (i, (k, d)) in hints.iter().enumerate() {
            if i > 0 {
                spans.push(Span::raw("  "));
            }
            spans.push(Span::styled(k.to_string(), Style::default().fg(theme.hint_key).add_modifier(Modifier::BOLD)));
            spans.push(Span::raw(" "));
            spans.push(Span::styled(d.to_string(), Style::default().fg(theme.hint)));
        }
        frame.render_widget(Paragraph::new(Line::from(spans)), hints_area);
    }

    // Overlays
    match app.mode {
        Mode::Help => {
            let popup = centered_rect(70, 80, main);
            frame.render_widget(Clear, popup);
            let block = WBlock::default()
                .borders(Borders::ALL)
                .title(" Help ")
                .border_style(Style::default().fg(theme.border_active))
                .style(Style::default().bg(theme.bg));
            let inner = block.inner(popup);
            frame.render_widget(block, popup);
            let all: Vec<&str> = HELP_TEXT.lines().collect();
            let max_scroll = all.len().saturating_sub(inner.height as usize);
            if app.help_scroll > max_scroll {
                app.help_scroll = max_scroll;
            }
            let lines: Vec<Line> = all
                .iter()
                .skip(app.help_scroll)
                .take(inner.height as usize)
                .map(|l| {
                    if !l.starts_with(' ') && !l.is_empty() && !l.starts_with("Use ") && !l.starts_with("Note") && !l.starts_with("results") {
                        Line::from(Span::styled(l.to_string(), Style::default().fg(theme.title).add_modifier(Modifier::BOLD)))
                    } else {
                        Line::from(Span::styled(l.to_string(), Style::default().fg(theme.fg)))
                    }
                })
                .collect();
            let text_area = Rect { x: inner.x, y: inner.y, width: inner.width.saturating_sub(1), height: inner.height };
            frame.render_widget(Paragraph::new(lines), text_area);
            let mut sb = ScrollbarState::new(all.len().max(1)).position(app.help_scroll);
            frame.render_stateful_widget(
                Scrollbar::new(ScrollbarOrientation::VerticalRight)
                    .begin_symbol(Some("↑"))
                    .end_symbol(Some("↓"))
                    .track_symbol(Some("║"))
                    .thumb_symbol("█")
                    .style(Style::default().fg(theme.scrollbar)),
                inner,
                &mut sb,
            );
        }
        Mode::Picker => {
            let popup = centered_rect(80, 70, main);
            frame.render_widget(Clear, popup);
            let block = WBlock::default()
                .borders(Borders::ALL)
                .title(" File Picker ")
                .border_style(Style::default().fg(theme.border_active))
                .style(Style::default().bg(theme.bg));
            let inner = block.inner(popup);
            frame.render_widget(block, popup);
            let visible = app.filtered_picker();
            let mut lines: Vec<Line> = Vec::new();
            let header = if app.picker_filter.is_empty() {
                format!(
                    "Markdown Files in Current Directory ({} found) - /: search, j/k: navigate, Enter: open, q: quit",
                    app.picker_files.len()
                )
            } else {
                format!("Filter: {}_ ({} matches)", app.picker_filter, visible.len())
            };
            lines.push(Line::from(Span::styled(header, Style::default().fg(theme.title))));
            lines.push(Line::from(""));
            let rows_available = inner.height.saturating_sub(2) as usize / 2;
            let start = app.picker_selected.saturating_sub(rows_available.saturating_sub(1));
            for (vi, &fi) in visible.iter().enumerate().skip(start).take(rows_available.max(1)) {
                let name = app.picker_files[fi].file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                let sel = vi == app.picker_selected;
                let text = format!("{} [{}] {}", if sel { "▶" } else { " " }, vi + 1, name);
                let style = if sel {
                    Style::default().fg(theme.selected_fg).bg(theme.selected_bg).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(theme.fg)
                };
                lines.push(Line::from(Span::styled(text, style)));
                lines.push(Line::from(""));
            }
            frame.render_widget(Paragraph::new(lines), inner);
        }
        Mode::Palette => {
            let popup = centered_rect(60, 60, main);
            frame.render_widget(Clear, popup);
            let block = WBlock::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(theme.border_active))
                .style(Style::default().bg(theme.bg));
            let inner = block.inner(popup);
            frame.render_widget(block, popup);
            let mut lines: Vec<Line> = vec![
                Line::from(Span::styled("Command Palette", Style::default().fg(theme.title).add_modifier(Modifier::BOLD))),
                Line::from(""),
                Line::from(format!(": {}█", app.palette_input)),
                Line::from(""),
            ];
            for (vi, &ci) in app.filtered_palette().iter().enumerate() {
                let (name, aliases, desc) = PALETTE_COMMANDS[ci];
                let sel = vi == app.palette_selected;
                let style = if sel {
                    Style::default().fg(theme.selected_fg).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(theme.fg)
                };
                lines.push(Line::from(Span::styled(
                    format!("{} {} ({})", if sel { "▸" } else { " " }, name, aliases),
                    style,
                )));
                if sel {
                    lines.push(Line::from(Span::styled(format!("    {}", desc), Style::default().fg(theme.hint))));
                }
            }
            frame.render_widget(Paragraph::new(lines), inner);
        }
        _ => {}
    }

    visible_height
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

fn tty_error() -> Option<String> {
    if std::io::stdin().is_terminal() {
        return None;
    }
    match std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
        Ok(_) => None,
        Err(e) => Some(format!("Cannot open /dev/tty: {}. Interactive mode requires a terminal.", e)),
    }
}

fn report_terminal_error(msg: &str) {
    eprintln!("Failed to enable raw mode: {}", msg);
    eprintln!("Note: When piping input, ensure you have a controlling terminal.");
    eprintln!("Error: ");
    eprintln!("   0: \x1b[91m{}\x1b[0m", msg);
    eprintln!();
    eprintln!("Location:");
    eprintln!("   \x1b[35msrc/main.rs\x1b[0m:\x1b[35m275\x1b[0m");
    eprintln!();
    eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
    eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
}

pub fn run(opts: TuiOptions) -> i32 {
    let mut config = Config::load();
    if opts.no_images {
        config.images_enabled = false;
    } else if opts.images {
        config.images_enabled = true;
    }
    if let Some(cm) = &opts.color_mode {
        config.color_mode = cm.clone();
    }
    let theme_idx = match &opts.theme {
        Some(t) => theme::theme_index(t),
        None => theme::theme_index(&config.theme),
    };

    // Determine what to open.
    let mut picker_dir: Option<PathBuf> = None;
    let mut picker_files: Vec<PathBuf> = Vec::new();
    let (content, label, path): (String, String, Option<PathBuf>) = if opts.files.is_empty() {
        picker_dir = Some(std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        (crate::PLACEHOLDER_DOC.to_string(), "stdin".to_string(), None)
    } else if opts.files.len() > 1 {
        picker_files = opts.files.iter().map(PathBuf::from).collect();
        (crate::PLACEHOLDER_DOC.to_string(), "stdin".to_string(), None)
    } else if opts.files[0] == "-" {
        let mut buf = String::new();
        if let Err(e) = std::io::stdin().read_to_string(&mut buf) {
            eprintln!("Error reading input: I/O error: {}", e);
            return 1;
        }
        if buf.is_empty() {
            eprintln!("Error reading input: Empty input provided");
            return 1;
        }
        (buf, "stdin".to_string(), None)
    } else {
        let p = PathBuf::from(&opts.files[0]);
        if p.is_dir() {
            picker_dir = Some(p);
            (crate::PLACEHOLDER_DOC.to_string(), "stdin".to_string(), None)
        } else {
            match std::fs::read(&p) {
                Ok(bytes) => match String::from_utf8(bytes) {
                    Ok(s) => {
                        let label = p.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                        (s, label, Some(p))
                    }
                    Err(_) => {
                        eprintln!("Error reading input: I/O error: stream did not contain valid UTF-8");
                        return 1;
                    }
                },
                Err(e) => {
                    eprintln!("Error reading input: I/O error: {}", e);
                    return 1;
                }
            }
        }
    };

    if let Some(msg) = tty_error() {
        report_terminal_error(&msg);
        return 1;
    }

    let content = normalize_input(&content);
    let doc = Document::parse(&content);
    let mut app = App::new(doc, label, path, config, theme_idx);
    if let Some(dir) = picker_dir {
        app.picker_files = list_markdown_files(&dir);
        app.mode = Mode::Picker;
    } else if !picker_files.is_empty() {
        app.picker_files = picker_files;
        app.mode = Mode::Picker;
    }

    if let Err(e) = enable_raw_mode() {
        report_terminal_error(&format!("{}. Interactive mode requires a terminal.", e));
        return 1;
    }
    let mut stdout = std::io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = match ratatui::Terminal::new(backend) {
        Ok(t) => t,
        Err(e) => {
            let _ = disable_raw_mode();
            eprintln!("Failed to create terminal: {}", e);
            return 1;
        }
    };

    let mut visible_height = 20usize;
    let result: std::io::Result<()> = (|| {
        loop {
            terminal.draw(|f| {
                visible_height = draw(f, &mut app);
            })?;
            if app.quit {
                break;
            }
            if event::poll(Duration::from_millis(100))? {
                match event::read()? {
                    Event::Key(key) => app.handle_key(key, visible_height),
                    Event::Resize(_, _) => {}
                    Event::Mouse(_) => {}
                    _ => {}
                }
            }
        }
        Ok(())
    })();

    let _ = disable_raw_mode();
    let _ = std::io::stdout().execute(LeaveAlternateScreen);
    let _ = terminal.show_cursor();

    // Persist configuration (theme / width) on exit.
    app.config.theme = app.theme().id.to_string();
    app.config.outline_width = app.outline_width;
    let _ = app.config.save();

    match result {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("Error: {}", e);
            1
        }
    }
}
