const PALETTE_COMMANDS: &[(&str, &str, &str)] = &[
    ("Save changes", "w, write, save", "Save pending edits to file"),
    ("Undo edit", "u, undo", "Undo the last edit"),
    ("Save width to config", "sw, savewidth", "Persist the outline width"),
