pub fn wrap_spans(spans: &[RSpan], width: usize, indent: &str) -> Vec<RLine> {
    let width = width.max(4);
    // Flatten into words; a word is a run of non-space characters possibly
    // spanning several styles, followed by its trailing spaces.
    #[derive(Clone)]
    struct Word {
        parts: Vec<RSpan>,
        width: usize,
        trailing: usize,
        newline_before: bool,
    }
    let mut words: Vec<Word> = Vec::new();
    let mut cur = Word { parts: Vec::new(), width: 0, trailing: 0, newline_before: false };
    let mut pending_newline = false;
    let flush = |words: &mut Vec<Word>, cur: &mut Word, pending_newline: &mut bool| {
        if !cur.parts.is_empty() || cur.trailing > 0 || *pending_newline {
            cur.newline_before = *pending_newline;
            *pending_newline = false;
            words.push(std::mem::replace(cur, Word { parts: Vec::new(), width: 0, trailing: 0, newline_before: false }));
        }
    };
    for (text, kind) in spans {
        for ch in text.chars() {
            if ch == '\\n' {
                flush(&mut words, &mut cur, &mut pending_newline);
                pending_newline = true;
                continue;
            }
            if ch == ' ' {
                cur.trailing += 1;
                continue;
            }
            if cur.trailing > 0 {
                flush(&mut words, &mut cur, &mut pending_newline);
            }
            match cur.parts.last_mut() {
                Some(last) if last.1 == *kind => last.0.push(ch),
                _ => cur.parts.push((ch.to_string(), *kind)),
            }
            cur.width += UnicodeWidthStr::width(ch.to_string().as_str());
        }
    }
    flush(&mut words, &mut cur, &mut pending_newline);
    if pending_newline {
        words.push(Word { parts: Vec::new(), width: 0, trailing: 0, newline_before: true });
    }

    let mut lines: Vec<RLine> = Vec::new();
    let mut line: RLine = Vec::new();
    let mut line_w = 0usize;
    let mut at_line_start = true;
    let push_part = |line: &mut RLine, part: &RSpan| match line.last_mut() {
        Some(last) if last.1 == part.1 => last.0.push_str(&part.0),
        _ => line.push(part.clone()),
    };
    for (wi, w) in words.iter().enumerate() {
        if w.newline_before {
            lines.push(std::mem::take(&mut line));
            line_w = 0;
            at_line_start = true;
            if !indent.is_empty() {
                line.push((indent.to_string(), Kind::Normal));
                line_w = indent.len();
            }
        }
        if w.parts.is_empty() {
            if wi == 0 && w.trailing > 0 {
                // leading indentation of the block
                line.push((" ".repeat(w.trailing), Kind::Normal));
                line_w += w.trailing;
            }
            continue;
        }
        if !at_line_start && line_w + w.width > width {
            lines.push(std::mem::take(&mut line));
            line_w = 0;
            if !indent.is_empty() {
                line.push((indent.to_string(), Kind::Normal));
                line_w = indent.len();
            }
        }
        for p in &w.parts {
            push_part(&mut line, p);
        }
        line_w += w.width;
        at_line_start = false;
        if w.trailing > 0 && line_w < width {
            let sp = " ".repeat(w.trailing.min(width - line_w));
            line_w += sp.len();
            push_part(&mut line, &(sp, w.parts.last().map(|p| p.1).unwrap_or(Kind::Normal)));
        }
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push(line);
    }
    for l in lines.iter_mut() {
        if let Some(last) = l.last_mut() {
            let t = last.0.trim_end().to_string();
            last.0 = t;
            if last.0.is_empty() {
                l.pop();
            }
        }
    }
