fn is_markdown(p: &Path) -> bool {
    p.extension()
        .and_then(|e| e.to_str())
        .map(|e| matches!(e.to_lowercase().as_str(), "md" | "markdown"))
        .unwrap_or(false)
}

fn complete_words(words: &[String], index: usize) -> Vec<String> {
    let current = words.get(index).cloned().unwrap_or_default();
    let prev = if index >= 1 { words.get(index - 1).cloned() } else { None };
    let mut out = Vec::new();

    // Values for options
    if let Some(p) = prev.as_deref() {
        let values: Option<Vec<&str>> = match p {
            "-o" | "--output" => Some(vec!["plain", "json", "tree"]),
            "--color-mode" => Some(vec!["auto", "rgb", "256"]),
            "--query-output" => Some(vec!["plain", "json", "json-pretty", "jsonl", "md", "tree"]),
            "--theme" => Some(vec![
                "OceanDark",
                "Nord",
                "Dracula",
                "Solarized",
                "Monokai",
                "Gruvbox",
                "TokyoNight",
                "CatppuccinMocha",
            ]),
            "--filter" | "-L" | "--level" | "-s" | "--section" | "-q" | "--query" => Some(vec![]),
            _ => None,
        };
        if let Some(vals) = values {
            return vals.into_iter().filter(|v| v.starts_with(&current)).map(|v| v.to_string()).collect();
        }
    }

    if current.starts_with("--") {
        out.extend(LONG_FLAGS.iter().filter(|f| f.starts_with(&current)).map(|f| f.to_string()));
        return out;
    }
    if current.starts_with('-') {
        out.extend(FLAGS.iter().filter(|f| f.starts_with(&current)).map(|f| f.to_string()));
        return out;
    }
    // subcommands
    let has_positional = words[1..index].iter().any(|w| !w.starts_with('-'));
    if !has_positional {
        for sc in ["at-line", "help"] {
            if sc.starts_with(&current) {
                out.push(sc.to_string());
            }
        }
    }
    // files
    let (dir, prefix) = match current.rfind('/') {
        Some(i) => (PathBuf::from(&current[..=i]), current[i + 1..].to_string()),
        None => (PathBuf::from("."), current.clone()),
    };
    let dir_display = match current.rfind('/') {
        Some(i) => current[..=i].to_string(),
        None => String::new(),
    };
    if let Ok(rd) = std::fs::read_dir(&dir) {
        let mut entries: Vec<(String, bool)> = rd
            .filter_map(|e| e.ok())
            .filter_map(|e| {
                let name = e.file_name().to_string_lossy().to_string();
                if !name.starts_with(&prefix) || (name.starts_with('.') && !prefix.starts_with('.')) {
                    return None;
                }
                let path = e.path();
                if path.is_dir() {
                    Some((name, true))
                } else if is_markdown(&path) {
                    Some((name, false))
                } else {
                    None
                }
            })
            .collect();
        entries.sort();
        for (name, is_dir) in entries {
            if is_dir {
                out.push(format!("{}{}/", dir_display, name));
            } else {
                out.push(format!("{}{}", dir_display, name));
            }
        }
    }
    out
}

/// Entry point when the `COMPLETE` environment variable is set.
pub fn run_complete_env(shell: &str) -> i32 {
    let args: Vec<String> = std::env::args().collect();
    let bin = "treemd";
    if args.len() >= 2 && args[1] == "--" {
        // dynamic completion request
        let words: Vec<String> = args[2..].to_vec();
        let index = std::env::var("_CLAP_COMPLETE_INDEX")
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(words.len().saturating_sub(1));
        let sep = std::env::var("_CLAP_IFS").unwrap_or_else(|_| "\n".to_string());
        let candidates = complete_words(&words, index.min(words.len().saturating_sub(1)));
        let mut stdout = std::io::stdout();
        let _ = write!(stdout, "{}", candidates.join(&sep));
        let _ = stdout.flush();
        return 0;
    }
    match registration(shell, bin, &exe_path()) {
        Some(script) => {
            print!("{}", script);
            0
        }
        None => {
            eprintln!(
                "error: unknown shell `{}`, expected one of `bash`, `elvish`, `fish`, `powershell`, `zsh`",
                shell
            );
            2
        }
    }
}
